(function () {
  "use strict";

  var pointerStarts = new WeakMap();

  function backdropCloseEnabled(element) {
    return element && element.getAttribute("data-backdrop-close") !== "false";
  }

  function isPrimaryPointer(event) {
    return event.button === undefined || event.button === 0;
  }

  function requestDialogClose(dialog) {
    if (!dialog.open || !backdropCloseEnabled(dialog)) return;

    var cancelEvent = new Event("cancel", { bubbles: false, cancelable: true });
    if (!dialog.dispatchEvent(cancelEvent) || !dialog.open) return;
    dialog.close("backdrop");
  }

  document.addEventListener("pointerdown", function (event) {
    if (!isPrimaryPointer(event)) return;

    var target = event.target;
    var dialog = target instanceof HTMLDialogElement
      ? target
      : target.closest && target.closest("dialog");
    if (dialog instanceof HTMLDialogElement && dialog.open) {
      pointerStarts.set(dialog, event.target === dialog);
      return;
    }

    var backdrop = event.target.closest && event.target.closest("[data-modal-backdrop]");
    if (backdrop) pointerStarts.set(backdrop, event.target === backdrop);
  });

  document.addEventListener("click", function (event) {
    if (!isPrimaryPointer(event)) return;

    var dialog = event.target;
    if (dialog instanceof HTMLDialogElement) {
      var startedOnBackdrop = pointerStarts.get(dialog);
      pointerStarts.delete(dialog);
      if (startedOnBackdrop !== true || event.target !== dialog) return;
      requestDialogClose(dialog);
      return;
    }

    var backdrop = event.target.closest && event.target.closest("[data-modal-backdrop]");
    if (!backdrop || event.target !== backdrop || !backdropCloseEnabled(backdrop)) return;

    var customStartedOnBackdrop = pointerStarts.get(backdrop);
    pointerStarts.delete(backdrop);
    if (customStartedOnBackdrop !== true) return;

    var closeUrl = backdrop.getAttribute("data-backdrop-close-url");
    if (closeUrl) window.location.assign(closeUrl);
  });

  document.addEventListener("pointercancel", function (event) {
    var target = event.target;
    var dialog = target instanceof HTMLDialogElement
      ? target
      : target.closest && target.closest("dialog");
    if (dialog instanceof HTMLDialogElement) pointerStarts.delete(dialog);
    var backdrop = target.closest && target.closest("[data-modal-backdrop]");
    if (backdrop) pointerStarts.delete(backdrop);
  });
})();

/* source: lazy-datalist.js */
/* Materialize large native datalists only when their input is used. */
(() => {
  "use strict";

  const parsedSources = new Map();

  function sourceValues(sourceId) {
    if (parsedSources.has(sourceId)) return parsedSources.get(sourceId);
    const source = document.getElementById(sourceId);
    let values = [];
    if (source) {
      try {
        const payload = JSON.parse(source.textContent || "[]");
        if (Array.isArray(payload)) values = payload;
      } catch {
        values = [];
      }
    }
    parsedSources.set(sourceId, values);
    return values;
  }

  function materialize(input) {
    const listId = input?.getAttribute?.("list") || "";
    if (!listId) return;
    const list = document.getElementById(listId);
    const sourceId = list?.dataset?.uposLazyDatalist || "";
    if (!list || !sourceId || list.dataset.uposLazyReady === "1") return;
    const fragment = document.createDocumentFragment();
    sourceValues(sourceId).forEach((value) => {
      const option = document.createElement("option");
      option.value = String(value ?? "");
      fragment.appendChild(option);
    });
    list.appendChild(fragment);
    list.dataset.uposLazyReady = "1";
  }

  ["pointerdown", "focusin", "keydown"].forEach((eventName) => {
    document.addEventListener(eventName, (event) => {
      const input = event.target instanceof Element ? event.target.closest("input[list]") : null;
      materialize(input);
    }, { capture: true, passive: true });
  });

  window.UPOSLazyDatalist = { materialize };
})();

/* source: workspace-section-reset.js */
(() => {
  "use strict";

  const routes = [
    { path: "/organizations/reports", keys: ["upos.generalReports.openTabs"] },
    { path: "/organizations/settings", keys: ["upos.orgSettings.openTabs"] },
    { path: "/organizations/users", keys: ["upos.orgSettings.openTabs"] },
    { path: "/settings", keys: ["upos.orgSettings.openTabs"] },
    { path: "/organizations/shipments", keys: ["upos.shipments.openTabs"] },
    { path: "/organizations/hr", keys: ["upos.hr.openTabs"] },
    { path: "/sales", keys: ["upos.sales.openTabs"] },
    {
      path: "/finance",
      keys: ["upos.finance.openTabs"],
      allowedPaths: ["/finance", "/schet", "/kassa", "/earnings"],
      lastUrlKey: "upos.finance.lastUrl",
    },
    { path: "/products", keys: ["upos.products.openTabs"] },
    { path: "/warehouse", keys: ["upos.warehouse.openTabs"] },
    { path: "/clients", keys: ["upos.clients.openTabs"] },
    { path: "/suppliers", keys: ["upos.suppliers.openTabs"] },
    { path: "/crm", keys: ["upos.crm.openTabs"] },
    { path: "/telephony", keys: ["upos.telephony.openTabs"] },
    { path: "/messengers", keys: ["upos.messengers.openTabs"] },
    { path: "/reports", keys: ["upos.homeReports.openTabs"] },
    { path: "/shipments", keys: ["upos.shipments.openTabs"] },
    { path: "/hr", keys: ["upos.hr.openTabs"] },
  ];

  function routeForHref(href) {
    try {
      const url = new URL(href, window.location.href);
      if (url.origin !== window.location.origin) return null;
      return routes.find((route) => url.pathname === route.path) || null;
    } catch {
      return null;
    }
  }

  function rememberedUrl(route) {
    try {
      if (route.lastUrlKey) {
        const stored = normalizeTabId(localStorage.getItem(route.lastUrlKey));
        if (stored) {
          const url = new URL(stored, window.location.origin);
          if (url.origin === window.location.origin && routeAllowsPath(route, url.pathname)) {
            return `${url.pathname}${url.search}${url.hash}`;
          }
        }
      }
      for (const key of route.keys) {
        const saved = JSON.parse(localStorage.getItem(key) || "{}");
        const tabId = normalizeTabId(saved.activeTab || saved.lastActiveTab);
        if (!tabId) continue;
        const storedUrl = normalizeTabId(saved.tabState?.[tabId]?.url);
        const meta = saved.meta?.[tabId];
        const fallback = normalizeTabId(meta?.href) || (meta?.hash ? `${route.path}#${meta.hash}` : "");
        const url = new URL(storedUrl || fallback, window.location.origin);
        if (route.path === "/sales" && tabId === "journal" && !url.searchParams.has("view")) {
          url.searchParams.set("view", "journal");
        }
        if (url.origin === window.location.origin && routeAllowsPath(route, url.pathname)) {
          return `${url.pathname}${url.search}${url.hash}`;
        }
      }
    } catch {}
    return "";
  }

  function normalizeTabId(value) {
    return String(value || "").trim();
  }

  function routeAllowsPath(route, pathname) {
    return (route.allowedPaths || [route.path]).includes(pathname);
  }

  function rememberCurrentSection() {
    routes.forEach((route) => {
      if (!route.lastUrlKey || !routeAllowsPath(route, window.location.pathname)) return;
      // Стартовая страница модуля не должна стирать последнюю рабочую вкладку.
      // Память очищается только явной кнопкой закрытия самой вкладки.
      if (window.location.pathname === route.path) return;
      localStorage.setItem(
        route.lastUrlKey,
        `${window.location.pathname}${window.location.search}${window.location.hash}`
      );
    });
  }

  function restoreSidebarLinks(scope = document) {
    scope.querySelectorAll("a.nav-link[href], a.nav-sublink[href]").forEach((link) => {
      const baseHref = link.dataset.workspaceBaseHref || link.getAttribute("href");
      const route = routeForHref(baseHref);
      if (!route) return;
      link.dataset.workspaceBaseHref = baseHref;
      if (link.classList.contains("active") && routeAllowsPath(route, window.location.pathname)) {
        link.setAttribute("href", baseHref);
        return;
      }
      const target = rememberedUrl(route);
      link.setAttribute("href", target || baseHref);
    });
  }

  document.addEventListener(
    "click",
    (event) => {
      const link = event.target.closest("a.nav-link[href], a.nav-sublink[href]");
      if (!link) return;
      const baseHref = link.dataset.workspaceBaseHref || link.getAttribute("href");
      const route = routeForHref(baseHref);
      if (!route) return;
      link.dataset.workspaceBaseHref = baseHref;
      if (link.classList.contains("active") && routeAllowsPath(route, window.location.pathname)) {
        link.setAttribute("href", baseHref);
        return;
      }
      const target = rememberedUrl(route);
      if (target) link.setAttribute("href", target);
    },
    true
  );

  window.addEventListener("storage", () => restoreSidebarLinks());

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      () => {
        rememberCurrentSection();
        restoreSidebarLinks();
      },
      { once: true }
    );
  } else {
    rememberCurrentSection();
    restoreSidebarLinks();
  }
})();

/* source: layout-sidebar.js */
(function () {
  var RAIL_STORAGE = "upos.sidebarRail";

  function isMobileNav() {
    return window.matchMedia("(max-width: 768px)").matches;
  }

  function readRailPref() {
    try {
      return window.localStorage.getItem(RAIL_STORAGE) === "1";
    } catch (e) {
      return false;
    }
  }

  function writeRailPref(on) {
    try {
      if (on) window.localStorage.setItem(RAIL_STORAGE, "1");
      else window.localStorage.removeItem(RAIL_STORAGE);
    } catch (e) {}
  }

  /** Desktop-only: narrow icon rail vs full sidebar width */
  function applySidebarRail(collapsed) {
    document.body.classList.toggle("sidebar-rail", collapsed);
    var btn = document.querySelector("[data-sidebar-rail-toggle]");
    if (btn) {
      btn.setAttribute("aria-expanded", collapsed ? "false" : "true");
      btn.setAttribute(
        "aria-label",
        collapsed ? "Развернуть боковое меню" : "Свернуть боковое меню",
      );
      btn.title = collapsed ? "Развернуть меню" : "Свернуть меню";
    }
  }

  function syncRailForViewport() {
    if (isMobileNav()) {
      applySidebarRail(false);
      return;
    }
    applySidebarRail(readRailPref());
  }

  function bootSidebarRail() {
    var btn = document.querySelector("[data-sidebar-rail-toggle]");
    syncRailForViewport();
    if (btn) {
      btn.addEventListener("click", function () {
        if (isMobileNav()) return;
        var next = !document.body.classList.contains("sidebar-rail");
        applySidebarRail(next);
        writeRailPref(next);
      });
    }
    window.addEventListener("resize", syncRailForViewport);
  }

  function sidebarCsrfToken() {
    var input = document.querySelector('input[name="csrf_token"]');
    return input ? String(input.value || "") : "";
  }

  function readJsonResponse(response) {
    return response.text().then(function (text) {
      var body = {};
      try {
        body = text ? JSON.parse(text) : {};
      } catch (e) {
        body = {};
      }
      if (!response.ok) {
        throw new Error(body.error || body.message || "Не удалось выполнить синхронизацию");
      }
      return body;
    });
  }

  function bootSidebarIboxSync() {
    var button = document.querySelector("[data-sidebar-ibox-sync]");
    if (!button) return;
    var STATUS_CACHE_KEY = "upos:ibox-status:v1";
    var STATUS_CACHE_TTL_MS = 30 * 1000;
    var statusNode = button.querySelector("[data-sidebar-ibox-sync-status]");
    var liveNode = document.querySelector("[data-sidebar-ibox-sync-live]");
    var lastSyncNode = button.querySelector("[data-sidebar-ibox-sync-last]");
    var pollTimer = 0;
    var resetTimer = 0;
    var MONTHS = ["янв", "фев", "мар", "апр", "мая", "июн", "июл", "авг", "сен", "окт", "ноя", "дек"];

    function formatSyncMoment(value) {
      var raw = String(value || "").trim();
      if (!raw) return "";
      var moment = new Date(raw);
      if (isNaN(moment.getTime())) return "";
      var time =
        String(moment.getHours()).padStart(2, "0") + ":" + String(moment.getMinutes()).padStart(2, "0");
      var today = new Date();
      var sameDay = function (a, b) {
        return (
          a.getFullYear() === b.getFullYear() &&
          a.getMonth() === b.getMonth() &&
          a.getDate() === b.getDate()
        );
      };
      if (sameDay(moment, today)) return "сегодня в " + time;
      var yesterday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1);
      if (sameDay(moment, yesterday)) return "вчера в " + time;
      var date = moment.getDate() + " " + MONTHS[moment.getMonth()];
      if (moment.getFullYear() !== today.getFullYear()) date += " " + moment.getFullYear();
      return date + ", " + time;
    }

    function showLastSync(value) {
      if (!lastSyncNode) return;
      var text = formatSyncMoment(value);
      lastSyncNode.textContent = text ? "Обновлено " + text : "";
      lastSyncNode.hidden = !text;
    }

    function setState(state, message, detail) {
      button.dataset.state = state;
      button.disabled = state === "running";
      if (statusNode) statusNode.textContent = message;
      button.title = detail || message;
      button.setAttribute("aria-label", detail || message);
      if (liveNode) liveNode.textContent = detail || message;
    }

    function resetCompletedState() {
      clearTimeout(resetTimer);
      resetTimer = window.setTimeout(function () {
        setState("idle", "Синхронизировать вручную", "Ручная синхронизация с IBOX");
      }, 5000);
    }

    function applyStatus(status, announce) {
      if (!status) {
        setState("idle", "Синхронизировать вручную", "Ручная синхронизация с IBOX");
        return false;
      }
      if (status.status === "running") {
        setState("running", "Синхронизация…", "IBOX: синхронизация выполняется");
        return true;
      }
      if (status.status === "error") {
        setState("error", "Ошибка синхронизации", status.error || "IBOX: ошибка синхронизации");
        return false;
      }
      if (status.status === "partial") {
        var warnings = status.data && Array.isArray(status.data.warnings)
          ? status.data.warnings.length
          : 0;
        var partialDetail =
          "IBOX: импортировано " +
          String(status.imported_count || 0) +
          ", недоступных разделов " +
          String(warnings);
        setState("partial", "Синхронизировано частично", partialDetail);
        if (announce) resetCompletedState();
        return false;
      }
      var detail = "IBOX: импортировано записей " + String(status.imported_count || 0);
      setState(announce ? "success" : "idle", announce ? "Данные обновлены" : "Синхронизировать вручную", detail);
      if (announce) resetCompletedState();
      return false;
    }

    function readCachedStatus() {
      try {
        var cached = JSON.parse(window.sessionStorage.getItem(STATUS_CACHE_KEY) || "null");
        if (!cached || !cached.at || !cached.body) return null;
        return cached;
      } catch (error) {
        return null;
      }
    }

    function cacheStatus(body) {
      try {
        window.sessionStorage.setItem(STATUS_CACHE_KEY, JSON.stringify({
          at: Date.now(),
          body: body,
        }));
      } catch (error) {}
    }

    function renderStatusBody(body, announce) {
      showLastSync(body && body.last_sync_at);
      return applyStatus(body && body.status, announce);
    }

    function pollStatus(announce, force) {
      clearTimeout(pollTimer);
      var cached = readCachedStatus();
      if (!force && !announce && cached) {
        var running = renderStatusBody(cached.body, false);
        if (!running && Date.now() - Number(cached.at) < STATUS_CACHE_TTL_MS) return;
      }
      if (!force && document.visibilityState === "hidden") return;
      fetch("/api/integrations/ibox/status", {
        headers: { Accept: "application/json" },
      })
        .then(readJsonResponse)
        .then(function (body) {
          cacheStatus(body);
          if (renderStatusBody(body, announce)) {
            pollTimer = window.setTimeout(function () {
              pollStatus(true, true);
            }, 1800);
          }
        })
        .catch(function (error) {
          setState("error", "Ошибка синхронизации", error.message || "IBOX недоступен");
        });
    }

    button.addEventListener("click", function () {
      if (button.disabled) return;
      clearTimeout(resetTimer);
      setState("running", "Запускаю…", "IBOX: запускаю полную синхронизацию");
      fetch("/api/integrations/ibox/sync", {
        method: "POST",
        headers: {
          Accept: "application/json",
          "X-CSRF-Token": sidebarCsrfToken(),
        },
      })
        .then(readJsonResponse)
        .then(function (body) {
          if (applyStatus(body.status, true)) {
            pollTimer = window.setTimeout(function () {
              pollStatus(true, true);
            }, 1200);
          } else {
            pollStatus(false, true);
          }
        })
        .catch(function (error) {
          setState("error", "Ошибка синхронизации", error.message || "Не удалось запустить синхронизацию IBOX");
        });
    });

    pollStatus(false, false);
    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") pollStatus(false, false);
    });
  }

  function setOpen(on) {
    var body = document.body;
    var toggle = document.querySelector("[data-sidebar-toggle]");
    var backdrop = document.querySelector("[data-sidebar-backdrop]");
    body.classList.toggle("layout-nav-open", on);
    if (toggle) {
      toggle.setAttribute("aria-expanded", on ? "true" : "false");
    }
    if (backdrop) {
      backdrop.hidden = !on;
      backdrop.setAttribute("aria-hidden", on ? "false" : "true");
    }
  }

  function boot() {
    bootSidebarRail();
    bootSidebarIboxSync();

    var toggle = document.querySelector("[data-sidebar-toggle]");
    var backdrop = document.querySelector("[data-sidebar-backdrop]");
    var sidebar = document.getElementById("app-sidebar");
    if (!toggle) return;

    toggle.addEventListener("click", function () {
      setOpen(!document.body.classList.contains("layout-nav-open"));
    });

    if (backdrop) {
      backdrop.addEventListener("click", function () {
        setOpen(false);
      });
    }

    if (sidebar) {
      sidebar.addEventListener(
        "click",
        function (ev) {
          var el = ev.target;
          if (!el || !el.closest) return;
          var a = el.closest("a[href]");
          if (!a) return;
          var href = a.getAttribute("href") || "";
          if (!href || href === "#") return;
          if (!isMobileNav()) return;
          setOpen(false);
        },
        true,
      );
    }

    window.addEventListener(
      "keydown",
      function (ev) {
        if (ev.key === "Escape" && document.body.classList.contains("layout-nav-open")) {
          setOpen(false);
          toggle.focus();
        }
      },
      true,
    );

    window.addEventListener("resize", function () {
      // Совпадает с CSS: мобильный drawer только при max-width 768px.
      if (window.matchMedia("(min-width: 769px)").matches) {
        setOpen(false);
      }
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

/* source: workspace-module-tabs.js */
(() => {
  "use strict";

  const controllers = new WeakMap();

  function normalize(value) {
    return String(value || "").trim();
  }

  function splitViews(value) {
    return normalize(value).split(/\s+/).filter(Boolean);
  }

  function unique(items) {
    return Array.from(new Set(items.filter(Boolean)));
  }

  function emptyState() {
    return {
      openTabs: [],
      activeTab: "",
      lastActiveTab: "",
      meta: {},
      tabState: {},
    };
  }

  function parseState(key) {
    try {
      const raw = JSON.parse(localStorage.getItem(key) || "{}");
      return {
        openTabs: Array.isArray(raw.openTabs) ? raw.openTabs : [],
        activeTab: typeof raw.activeTab === "string" ? raw.activeTab : "",
        lastActiveTab: typeof raw.lastActiveTab === "string" ? raw.lastActiveTab : "",
        meta: raw.meta && typeof raw.meta === "object" ? raw.meta : {},
        tabState: raw.tabState && typeof raw.tabState === "object" ? raw.tabState : {},
      };
    } catch {
      return emptyState();
    }
  }

  function resolveTabId(source) {
    return normalize(
      source?.dataset.workspaceTabId ||
        source?.dataset.workspaceCard ||
        source?.dataset.workspaceTrigger ||
        source?.dataset.workspaceOpenTab
    );
  }

  function resolveViewId(source, fallback = "") {
    return normalize(
      source?.dataset.workspaceViewId ||
        source?.dataset.workspaceCard ||
        source?.dataset.workspaceTrigger ||
        fallback
    );
  }

  function createController(root) {
    const existingController = controllers.get(root);
    if (existingController) {
      existingController.refresh();
      return existingController;
    }
    if (root.dataset.workspaceTabsReady === "1") return null;

    const key = normalize(root.dataset.workspaceKey);
    const tabsShell = root.querySelector("[data-workspace-open-tabs]");
    const homeTab = root.querySelector("[data-workspace-home-tab]");
    const launcher = root.querySelector("[data-workspace-launcher]");
    if (!key || !tabsShell || !homeTab) return null;
    root.dataset.workspaceTabsReady = "1";

    const storageKey = `upos.${key}.openTabs`;
    const tabMeta = new Map();
    let openTabs = [];
    let activeTab = "";
    let lastActiveTab = "";
    let tabState = {};
    let lastSerializedState = "";
    let renderedView = "";

    function homeUrl() {
      const href = root.dataset.workspaceHomeHref || homeTab.getAttribute("href") || "";
      return href ? new URL(href, window.location.href) : new URL(window.location.href);
    }

    function registerMeta(source) {
      const tabId = resolveTabId(source);
      if (!tabId) return "";
      const existing = tabMeta.get(tabId) || {};
      const viewId = resolveViewId(source) || existing.viewId || tabId;
      const title =
        normalize(source.dataset.workspaceTabTitle) ||
        normalize(source.dataset.workspaceTitle) ||
        normalize(source.querySelector?.("[data-workspace-activate-tab]")?.textContent) ||
        normalize(source.textContent) ||
        existing.title ||
        tabId;
      const hash = normalize(
        source.dataset.workspaceTabHash || source.dataset.workspaceHash || existing.hash || tabId
      ).replace(/^#/, "");
      const href = normalize(
        source.dataset.workspaceTabHref ||
          source.getAttribute("href") ||
          existing.href ||
          source.dataset.workspaceSyncUrl ||
          ""
      );
      tabMeta.set(tabId, { id: tabId, viewId, title, hash, href });
      return tabId;
    }

    function collectMeta() {
      root
        .querySelectorAll("[data-workspace-card], [data-workspace-trigger], [data-workspace-open-tab]")
        .forEach(registerMeta);
    }

    function hydrateSavedMeta(savedMeta) {
      Object.entries(savedMeta || {}).forEach(([tabId, item]) => {
        if (!tabId || !item || typeof item !== "object") return;
        tabMeta.set(tabId, {
          id: tabId,
          viewId: normalize(item.viewId) || tabId,
          title: normalize(item.title) || tabId,
          hash: normalize(item.hash) || tabId,
          href: normalize(item.href),
        });
      });
    }

    function canonicalTabUrl(tabId) {
      const meta = tabMeta.get(tabId);
      if (!meta) return null;
      const base = meta.href || `${window.location.pathname}${window.location.search}`;
      const url = new URL(base, window.location.href);
      if (meta.hash) url.hash = meta.hash;
      return url;
    }

    function rememberedTabUrl(tabId) {
      const remembered = normalize(tabState[tabId]?.url);
      if (!remembered) return null;
      try {
        const url = new URL(remembered, window.location.origin);
        const meta = tabMeta.get(tabId);
        const expectedHash = normalize(meta?.hash).replace(/^#/, "");
        const rememberedHash = normalize(url.hash).replace(/^#/, "");
        if (expectedHash && rememberedHash !== expectedHash) {
          delete tabState[tabId];
          return null;
        }
        if (key === "sales" && tabId === "journal" && !url.searchParams.has("view")) {
          url.searchParams.set("view", "journal");
        }
        return url.origin === window.location.origin ? url : null;
      } catch {
        return null;
      }
    }

    function tabUrl(tabId) {
      return rememberedTabUrl(tabId) || canonicalTabUrl(tabId);
    }

    function matchesLocation(url, includeHash = false) {
      if (!url) return false;
      if (url.pathname !== window.location.pathname || url.search !== window.location.search) return false;
      return !includeHash || normalize(url.hash) === normalize(window.location.hash);
    }

    function tabFromLocation() {
      const hash = normalize(window.location.hash).replace(/^#/, "");
      const aliasMap = { telephony: { providers: "integrations" } };
      const aliasTab = aliasMap[key]?.[hash];
      if (aliasTab && tabMeta.has(aliasTab)) return aliasTab;

      if (key === "products" && hash === "price-type-detail") {
        const priceTypeId = new URLSearchParams(window.location.search).get("price_type");
        const priceTab = priceTypeId ? `price-type-${priceTypeId}` : "";
        if (priceTab && tabMeta.has(priceTab)) return priceTab;
      }

      if (hash && tabMeta.has(hash)) return hash;
      if (hash) {
        for (const [tabId, meta] of tabMeta.entries()) {
          if (meta.hash === hash) return tabId;
        }
      }
      for (const tabId of tabMeta.keys()) {
        if (matchesLocation(tabUrl(tabId), true)) return tabId;
      }
      if (!hash) return "";
      return "";
    }

    function ensureOpen(tabId) {
      if (tabId && !openTabs.includes(tabId)) openTabs.push(tabId);
    }

    function currentUrl() {
      return `${window.location.pathname}${window.location.search}${window.location.hash}`;
    }

    function rememberTab(tabId) {
      if (!tabId || !tabMeta.has(tabId)) return;
      const meta = tabMeta.get(tabId);
      const expectedHash = normalize(meta?.hash).replace(/^#/, "");
      const currentHash = normalize(window.location.hash).replace(/^#/, "");
      if (expectedHash && currentHash !== expectedHash) return;
      tabState[tabId] = { url: currentUrl() };
    }

    function saveState() {
      try {
        const meta = {};
        openTabs.forEach((tabId) => {
          const item = tabMeta.get(tabId);
          if (!item) return;
          meta[tabId] = {
            title: item.title,
            hash: item.hash,
            href: item.href,
            viewId: item.viewId,
          };
        });
        const serialized = JSON.stringify({ openTabs, activeTab, lastActiveTab, meta, tabState });
        if (serialized === lastSerializedState) return;
        localStorage.setItem(storageKey, serialized);
        lastSerializedState = serialized;
      } catch {}
    }

    function loadState() {
      const saved = parseState(storageKey);
      hydrateSavedMeta(saved.meta);
      collectMeta();
      openTabs = unique(saved.openTabs.filter((tabId) => tabMeta.has(tabId)));
      tabState = saved.tabState;

      const storedActive = tabMeta.has(saved.activeTab) ? saved.activeTab : "";
      lastActiveTab = tabMeta.has(saved.lastActiveTab) ? saved.lastActiveTab : storedActive;
      const defaultTab = normalize(root.dataset.workspaceDefaultTab);
      const forceTab = normalize(root.dataset.workspaceForceTab);
      const closeTabsOnLoad = splitViews(root.dataset.workspaceCloseTabsOnLoad);
      const hashTab = tabFromLocation();
      const hasLocationHash = Boolean(normalize(window.location.hash).replace(/^#/, ""));

      if (closeTabsOnLoad.length) {
        openTabs = openTabs.filter((tabId) => !closeTabsOnLoad.includes(tabId));
      }
      if (forceTab && tabMeta.has(forceTab)) {
        activeTab = forceTab;
      } else if (hashTab) {
        activeTab = hashTab;
      } else if (defaultTab && tabMeta.has(defaultTab)) {
        activeTab = defaultTab;
      } else if (hasLocationHash && storedActive && matchesLocation(tabUrl(storedActive))) {
        activeTab = storedActive;
      } else {
        activeTab = "";
      }

      if (activeTab) {
        lastActiveTab = activeTab;
        ensureOpen(activeTab);
      }
    }

    function syncLocalUrl(url) {
      if (!window.history?.replaceState || !url) return;
      window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
      if (activeTab) rememberTab(activeTab);
      saveState();
    }

    function renderViews() {
      const currentView = activeTab ? tabMeta.get(activeTab)?.viewId || activeTab : "home";
      if (launcher) launcher.hidden = Boolean(activeTab);
      root.querySelectorAll("[data-workspace-view]").forEach((node) => {
        const views = splitViews(node.dataset.workspaceView);
        node.hidden = views.length ? !views.includes(currentView) : false;
      });
      root.querySelectorAll("[data-workspace-card]").forEach((card) => {
        const isActive = Boolean(activeTab) && normalize(card.dataset.workspaceCard) === currentView;
        card.classList.toggle("active", isActive);
        if (isActive) card.setAttribute("aria-current", "page");
        else card.removeAttribute("aria-current");
      });
      if (renderedView !== currentView) {
        renderedView = currentView;
        root.dispatchEvent(new CustomEvent("upos:workspace-view-change", {
          bubbles: true,
          detail: { key, viewId: currentView, activeTab },
        }));
      }
    }

    function buildTabNode(tabId) {
      const holder = document.createElement("span");
      holder.className = "general-module-tab general-module-tab--report";
      holder.dataset.workspaceOpenTab = tabId;

      const syncButton = document.createElement("button");
      syncButton.type = "button";
      syncButton.className = "general-module-tab-sync";
      syncButton.title = "\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c";
      syncButton.setAttribute(
        "aria-label",
        "\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c"
      );
      syncButton.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
        '<path d="M3 12a9 9 0 0 1 14.7-7" /><path d="M17.7 5H13" /><path d="M17.7 5v4.7" />' +
        '<path d="M21 12a9 9 0 0 1-14.7 7" /><path d="M6.3 19H11" /><path d="M6.3 19v-4.7" /></svg>';

      const activateButton = document.createElement("button");
      activateButton.type = "button";
      activateButton.className = "general-module-tab-activate";
      activateButton.dataset.workspaceActivateTab = tabId;

      const closeButton = document.createElement("button");
      closeButton.type = "button";
      closeButton.className = "general-module-tab-close";
      closeButton.dataset.workspaceCloseTab = tabId;
      closeButton.textContent = "\u00d7";

      holder.append(syncButton, activateButton, closeButton);
      return holder;
    }

    function renderTabs() {
      const homeActive = !activeTab;
      homeTab.classList.toggle("active", homeActive);
      homeTab.setAttribute("aria-current", homeActive ? "page" : "false");

      const existing = new Map();
      tabsShell.querySelectorAll("[data-workspace-open-tab]").forEach((node) => {
        const tabId = normalize(node.dataset.workspaceOpenTab);
        if (tabId && !existing.has(tabId)) existing.set(tabId, node);
        else node.remove();
      });

      let previous = homeTab;
      openTabs.forEach((tabId) => {
        const meta = tabMeta.get(tabId);
        if (!meta) return;
        let holder = existing.get(tabId);
        if (holder) existing.delete(tabId);
        else holder = buildTabNode(tabId);

        holder.classList.toggle("active", tabId === activeTab);
        holder.dataset.workspaceHash = meta.hash;
        const url = tabUrl(tabId);
        if (url) holder.dataset.workspaceSyncUrl = url.toString();
        const activate = holder.querySelector("[data-workspace-activate-tab]");
        if (activate) activate.textContent = meta.title;
        holder
          .querySelector("[data-workspace-close-tab]")
          ?.setAttribute("aria-label", `\u0417\u0430\u043a\u0440\u044b\u0442\u044c ${meta.title}`);

        if (previous.nextElementSibling !== holder) previous.after(holder);
        previous = holder;
      });
      existing.forEach((node) => node.remove());
    }

    function render() {
      renderTabs();
      renderViews();
    }

    function openTab(tabId, options = {}) {
      if (!tabMeta.has(tabId)) return;
      if (activeTab) rememberTab(activeTab);
      ensureOpen(tabId);
      activeTab = tabId;
      lastActiveTab = tabId;
      saveState();

      const url = options.url ? new URL(options.url, window.location.href) : tabUrl(tabId);
      if (options.navigate !== false && url && !matchesLocation(url)) {
        render();
        window.location.assign(url.toString());
        return;
      }
      render();
      if (url) syncLocalUrl(url);
    }

    function goHome(options = {}) {
      const homeTabId = normalize(root.dataset.workspaceHomeTabId);
      if (homeTabId && tabMeta.has(homeTabId)) {
        openTab(homeTabId, options);
        return;
      }
      if (activeTab) rememberTab(activeTab);
      activeTab = "";
      saveState();
      const url = homeUrl();
      if (options.navigate !== false && (!matchesLocation(url) || window.location.hash)) {
        window.location.assign(url.toString());
        return;
      }
      render();
      window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
    }

    function closeTab(tabId) {
      const index = openTabs.indexOf(tabId);
      if (index >= 0) openTabs.splice(index, 1);
      if (activeTab === tabId) activeTab = openTabs[index] || openTabs[index - 1] || "";
      delete tabState[tabId];
      if (lastActiveTab === tabId) lastActiveTab = activeTab;
      saveState();

      const url = activeTab ? tabUrl(activeTab) : homeUrl();
      if (url && (!matchesLocation(url) || normalize(url.hash) !== normalize(window.location.hash))) {
        window.location.assign(url.toString());
        return;
      }
      render();
      if (url) syncLocalUrl(url);
    }

    function bind() {
      homeTab.addEventListener("click", (event) => {
        event.preventDefault();
        goHome({ navigate: true });
      });

      root.addEventListener("click", (event) => {
        const homeTrigger = event.target.closest("[data-workspace-home-trigger]");
        if (homeTrigger && root.contains(homeTrigger)) {
          event.preventDefault();
          goHome({ navigate: true });
          return;
        }
        const trigger = event.target.closest("[data-workspace-card], [data-workspace-trigger]");
        if (!trigger || !root.contains(trigger)) return;
        const tabId = registerMeta(trigger);
        if (!tabId) return;
        event.preventDefault();
        openTab(tabId, {
          navigate: true,
          url: normalize(trigger.dataset.workspaceNavigateHref),
        });
      });

      tabsShell.addEventListener("click", (event) => {
        const closeButton = event.target.closest("[data-workspace-close-tab]");
        if (closeButton) {
          event.preventDefault();
          event.stopPropagation();
          closeTab(normalize(closeButton.dataset.workspaceCloseTab));
          return;
        }
        const activateButton = event.target.closest("[data-workspace-activate-tab]");
        if (!activateButton) return;
        event.preventDefault();
        openTab(normalize(activateButton.dataset.workspaceActivateTab), { navigate: true });
      });

      root.addEventListener(
        "submit",
        (event) => {
          const form = event.target;
          if (!(form instanceof HTMLFormElement)) return;
          if ((form.getAttribute("method") || "get").toLowerCase() !== "get" || !activeTab) return;
          const meta = tabMeta.get(activeTab);
          if (!meta?.hash) return;
          try {
            const url = new URL(form.getAttribute("action") || window.location.href, window.location.href);
            form.setAttribute("action", `${url.pathname}${url.search}#${meta.hash}`);
          } catch {}
        },
        true
      );

      window.addEventListener("hashchange", () => {
        const nextTab = tabFromLocation();
        const hasHash = Boolean(normalize(window.location.hash).replace(/^#/, ""));
        if (nextTab) {
          ensureOpen(nextTab);
          activeTab = nextTab;
          lastActiveTab = nextTab;
          rememberTab(nextTab);
          saveState();
          render();
        } else if (!hasHash) {
          activeTab = "";
          saveState();
          render();
        }
      });

      window.addEventListener("pagehide", () => {
        if (activeTab) rememberTab(activeTab);
        saveState();
      });
    }

    loadState();
    bind();
    render();
    saveState();
    if (activeTab) {
      const url = tabUrl(activeTab);
      if (url && matchesLocation(url)) syncLocalUrl(url);
    }

    const controller = {
      openTab,
      goHome,
      refresh() {
        collectMeta();
        render();
      },
    };
    controllers.set(root, controller);
    return controller;
  }

  function init(scope = document) {
    scope.querySelectorAll("[data-workspace-tabs]").forEach(createController);
  }

  window.initWorkspaceModuleTabs = init;
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => init(), { once: true });
  } else {
    init();
  }
})();

/* source: module-tabs-sync.js */
(() => {
  const STATE_KEY = 'upos.moduleSync.state';

  function locationKey(url) {
    const clean = new URL(url.toString());
    clean.searchParams.delete('t');
    clean.searchParams.delete('fresh');
    return `${clean.pathname}${clean.search}`;
  }

  function scrollPanels() {
    const seen = [];
    document.querySelectorAll('[data-sync-scroll-key]').forEach((node) => {
      seen.push({ key: node.dataset.syncScrollKey, top: node.scrollTop });
    });
    return seen;
  }

  function rememberState(url) {
    try {
      const payload = {
        key: locationKey(url),
        hash: (url.hash || window.location.hash || '').replace(/^#/, ''),
        y: window.scrollY || document.documentElement.scrollTop || 0,
        panels: scrollPanels(),
        at: Date.now(),
      };
      window.sessionStorage.setItem(STATE_KEY, JSON.stringify(payload));
    } catch (err) {
      /* storage may be unavailable */
    }
  }

  function applyScroll(state) {
    if (state.y) window.scrollTo(0, state.y);
    (state.panels || []).forEach((panel) => {
      if (!panel || !panel.key || !panel.top) return;
      const node = document.querySelector(`[data-sync-scroll-key="${panel.key}"]`);
      if (node) node.scrollTop = panel.top;
    });
  }

  function restoreState() {
    let state = null;
    try {
      const raw = window.sessionStorage.getItem(STATE_KEY);
      if (!raw) return;
      state = JSON.parse(raw);
      window.sessionStorage.removeItem(STATE_KEY);
    } catch (err) {
      return;
    }
    if (!state || state.key !== locationKey(new URL(window.location.href))) return;
    if (!state.at || Date.now() - state.at > 30000) return;
    if (!state.y && !(state.panels || []).some((panel) => panel && panel.top)) return;
    requestAnimationFrame(() => applyScroll(state));
    window.setTimeout(() => applyScroll(state), 260);
    window.setTimeout(() => applyScroll(state), 700);
  }

  function goSync(url) {
    rememberState(url);
    window.location.assign(url.toString());
  }

  function tabHash(button) {
    const tab = button.closest('.general-module-tab--report');
    if (!tab) return '';
    const candidates = [
      tab.dataset.workspaceHash,
      tab.dataset.workspaceOpenTab,
      tab.dataset.hrOpenTab,
      tab.dataset.shipmentOpenTab,
      tab.dataset.orgSettingsOpenTab,
      tab.getAttribute('data-report-open-tab'),
      tab.getAttribute('data-org-report-open-tab'),
    ];
    const raw = candidates.find(Boolean);
    return raw ? `#${raw}` : '';
  }

  function syncNow(button) {
    if (button.disabled) return;
    button.disabled = true;
    button.classList.add('is-syncing');
    button.setAttribute('aria-label', '\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u044f');

    const workspaceUrl = button.closest('.general-module-tab--report')?.dataset.workspaceSyncUrl;
    if (workspaceUrl) {
      const target = new URL(workspaceUrl, window.location.href);
      if (!target.hash) target.hash = tabHash(button);
      if (target.pathname === window.location.pathname) {
        new URL(window.location.href).searchParams.forEach((value, name) => {
          if (name === 't' || name === 'fresh') return;
          if (!target.searchParams.has(name)) target.searchParams.append(name, value);
        });
      }
      target.searchParams.set('t', String(Date.now()));
      goSync(target);
      return;
    }

    const url = new URL(window.location.href);
    url.searchParams.set('t', String(Date.now()));
    const settingsTab = button.closest('.general-module-tab--report')?.dataset.orgSettingsOpenTab;
    if (settingsTab) {
      url.searchParams.set('tab', settingsTab);
      goSync(url);
      return;
    }
    const hash = tabHash(button);
    if (hash) url.hash = hash;
    goSync(url);
  }

  function syncStaticTab(icon) {
    const tab = icon.closest('.general-module-tab, .settings-tab--rail');
    if (!tab) return;
    const url = new URL(window.location.href);
    const href = tab.getAttribute('href');
    if (href) {
      const target = new URL(href, window.location.href);
      target.searchParams.set('t', String(Date.now()));
      goSync(target);
      return;
    }
    const settingsTab = tab.getAttribute('data-settings-tab');
    if (settingsTab) {
      url.searchParams.set('tab', settingsTab);
    }
    const hrTab = tab.getAttribute('data-hr-home-tab');
    const shipmentTab = tab.getAttribute('data-shipment-home-tab');
    const reportTab = tab.getAttribute('data-report-home-tab') || tab.getAttribute('data-org-report-home-tab');
    if (hrTab || shipmentTab || reportTab) {
      url.hash = '';
    }
    url.searchParams.set('t', String(Date.now()));
    goSync(url);
  }

  function createButton() {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'general-module-tab-sync';
    button.title = '\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c';
    button.setAttribute('aria-label', '\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c');
    button.innerHTML = `
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M3 12a9 9 0 0 1 14.7-7" />
        <path d="M17.7 5H13" />
        <path d="M17.7 5v4.7" />
        <path d="M21 12a9 9 0 0 1-14.7 7" />
        <path d="M6.3 19H11" />
        <path d="M6.3 19v-4.7" />
      </svg>
    `;
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      syncNow(button);
    });
    return button;
  }

  function mountReportTab(tab) {
    const existing = tab.querySelector('.general-module-tab-sync');
    if (existing) {
      // Кнопку уже создал workspace-module-tabs.js (чтобы ⟳ не мигала при
      // перезагрузке) — навешиваем обработчик один раз на готовую кнопку.
      if (existing.dataset.syncBound === '1') return;
      existing.dataset.syncBound = '1';
      existing.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        syncNow(existing);
      });
      return;
    }
    const activate = tab.querySelector('.general-module-tab-activate');
    if (!activate) return;
    tab.insertBefore(createButton(), activate);
  }

  function createStaticIcon() {
    const icon = document.createElement('span');
    icon.className = 'general-module-tab-sync-icon';
    icon.setAttribute('role', 'button');
    icon.setAttribute('tabindex', '0');
    icon.setAttribute('aria-label', '\u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c');
    icon.innerHTML = createButton().innerHTML;
    icon.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      syncStaticTab(icon);
    });
    icon.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      event.stopPropagation();
      syncStaticTab(icon);
    });
    return icon;
  }

  function mountStaticTab(tab) {
    if (tab.classList.contains('general-module-tab--report')) return;
    tab.querySelector('.general-module-tab-sync-icon')?.remove();
  }

  function mount() {
    document.querySelectorAll('.general-module-tab--report').forEach(mountReportTab);
    document.querySelectorAll('.general-module-tabs .general-module-tab, .settings-tablist--rail .settings-tab--rail').forEach(mountStaticTab);
    document.querySelectorAll('.general-module-tabs').forEach((tabs) => {
      if (tabs.dataset.moduleTabsSyncObserver === '1') return;
      tabs.dataset.moduleTabsSyncObserver = '1';
      new MutationObserver(() => {
        tabs.querySelectorAll('.general-module-tab--report').forEach(mountReportTab);
        tabs.querySelectorAll('.general-module-tab').forEach(mountStaticTab);
      }).observe(tabs, { childList: true, subtree: true });
    });
    document.querySelectorAll('.settings-tablist--rail').forEach((tabs) => {
      if (tabs.dataset.moduleTabsSyncObserver === '1') return;
      tabs.dataset.moduleTabsSyncObserver = '1';
      new MutationObserver(() => {
        tabs.querySelectorAll('.settings-tab--rail').forEach(mountStaticTab);
      }).observe(tabs, { childList: true, subtree: true });
    });
  }

  function boot() {
    mount();
    restoreState();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();

/* source: cell-title.js */
/* Полный текст ячейки при наведении: если содержимое обрезано (ellipsis),
   браузерная подсказка показывает его целиком. Работает во всех таблицах. */
(() => {
  document.addEventListener("mouseover", (event) => {
    const cell = event.target.closest("td, th");
    if (!cell || cell.dataset.cellTitleDone === "1") return;
    cell.dataset.cellTitleDone = "1";
    if (cell.getAttribute("title")) return;
    // Служебные значки (стрелки сортировки и т.п.) в подсказку не попадают.
    const clone = cell.cloneNode(true);
    clone.querySelectorAll('[aria-hidden="true"]').forEach((el) => el.remove());
    const text = (clone.textContent || "").replace(/\s+/g, " ").trim();
    if (!text) return;
    // Обрезан сам td или любой из вложенных блоков с ellipsis.
    const clipped = [cell, ...cell.querySelectorAll("*")].some(
      (el) => el.scrollWidth > el.clientWidth + 1
    );
    if (clipped) cell.title = text;
  });
})();

/* source: uz-phone.js */
/* Шаблон узбекского номера: поля с data-uz-phone форматируются при вводе
   как +998 90 123 45 67. Цифры можно вводить как с кодом страны, так и без. */
(() => {
  function formatUzPhone(field) {
    let digits = String(field.value || "").replace(/\D/g, "");
    if (digits.startsWith("998")) digits = digits.slice(3);
    digits = digits.slice(0, 9);
    if (!digits) {
      field.value = "";
      return;
    }
    let out = "+998 " + digits.slice(0, 2);
    if (digits.length > 2) out += " " + digits.slice(2, 5);
    if (digits.length > 5) out += " " + digits.slice(5, 7);
    if (digits.length > 7) out += " " + digits.slice(7, 9);
    field.value = out;
  }

  document.addEventListener("input", (event) => {
    const field = event.target;
    if (!(field instanceof HTMLInputElement) || !field.hasAttribute("data-uz-phone")) return;
    formatUzPhone(field);
  });
})();

/* source: ajax-sections.js */
/* Updates server-rendered sections without reloading the application shell. */
(() => {
  "use strict";

  const CACHE_TTL_MS = 2 * 60_000;
  const CACHE_LIMIT = 32;
  const responseCache = new Map();
  const prefetchRequests = new Map();
  const latestLoads = new Map();
  const loadControllers = new Map();
  let loadSequence = 0;

  function reinit(names) {
    (names || []).forEach((name) => {
      const fn = window[name];
      if (typeof fn !== "function") return;
      try {
        fn(document);
      } catch {
        /* One optional module must not stop the rest of the page. */
      }
    });
  }

  function readConfig(source) {
    const owner = source?.closest?.("[data-ajax-targets]") || source;
    return {
      targets: (owner?.getAttribute?.("data-ajax-targets") || "")
        .split(",")
        .map((value) => value.trim())
        .filter(Boolean),
      reinitNames: (owner?.getAttribute?.("data-ajax-reinit") || "")
        .split(",")
        .map((value) => value.trim())
        .filter(Boolean),
    };
  }

  function swapHtml(html, selectors) {
    const parsed = new DOMParser().parseFromString(html, "text/html");
    let swapped = 0;
    selectors.forEach((selector) => {
      const fresh = parsed.querySelector(selector);
      const current = document.querySelector(selector);
      if (fresh && current && current.isConnected) {
        current.replaceWith(fresh);
        swapped += 1;
      }
    });
    return swapped;
  }

  function remember(href, html) {
    responseCache.delete(href);
    responseCache.set(href, { html, expiresAt: Date.now() + CACHE_TTL_MS });
    while (responseCache.size > CACHE_LIMIT) {
      responseCache.delete(responseCache.keys().next().value);
    }
    return html;
  }

  function cachedHtml(href) {
    const cached = responseCache.get(href);
    if (cached && cached.expiresAt > Date.now()) {
      responseCache.delete(href);
      responseCache.set(href, cached);
      return cached.html;
    }
    if (cached) responseCache.delete(href);
    return null;
  }

  function fetchHtml(href, signal) {
    const cached = cachedHtml(href);
    if (cached !== null) return Promise.resolve(cached);

    return fetch(href, {
      headers: { "X-Requested-With": "XMLHttpRequest" },
      credentials: "same-origin",
      signal,
    })
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.text();
      })
      .then((html) => remember(href, html));
  }

  function prefetch(href) {
    if (!href || href.startsWith("#")) return;
    if (cachedHtml(href) !== null || prefetchRequests.has(href)) return;
    const pending = fetchHtml(href)
      .catch(() => null)
      .finally(() => prefetchRequests.delete(href));
    prefetchRequests.set(href, pending);
  }

  async function loadHtml(href, signal) {
    const pending = prefetchRequests.get(href);
    if (pending) {
      const prefetched = await pending;
      if (prefetched !== null) return prefetched;
    }
    return fetchHtml(href, signal);
  }

  function loadKey(targets) {
    return [...targets].sort().join("|");
  }

  async function load(href, source, options = {}) {
    const config = options.config || readConfig(source);
    const { targets, reinitNames } = config;
    if (!targets.length) {
      window.location.href = href;
      return;
    }

    const key = loadKey(targets);
    loadControllers.get(key)?.abort();
    const controller = new AbortController();
    loadControllers.set(key, controller);
    const token = ++loadSequence;
    latestLoads.set(key, token);
    const currentTargets = targets.map((selector) => document.querySelector(selector)).filter(Boolean);
    const scrollX = window.scrollX;
    const scrollY = window.scrollY;
    const busyTimer = window.setTimeout(() => {
      if (latestLoads.get(key) !== token) return;
      currentTargets.forEach((node) => node.setAttribute("aria-busy", "true"));
    }, 140);

    try {
      const html = await loadHtml(href, controller.signal);
      if (latestLoads.get(key) !== token) return;
      if (!swapHtml(html, targets)) throw new Error("targets not found");

      if (options.history !== false) {
        const currentState = window.history.state && typeof window.history.state === "object"
          ? window.history.state
          : {};
        if (!currentState.ajaxSection) {
          window.history.replaceState({ ...currentState, ajaxSection: config }, "", window.location.href);
        }
        const nextState = { ajaxSection: config };
        if (options.history === "replace") {
          window.history.replaceState(nextState, "", href);
        } else {
          window.history.pushState(nextState, "", href);
        }
      }

      reinit(reinitNames);
      if (typeof window.initWorkspaceModuleTabs === "function") {
        window.initWorkspaceModuleTabs(document);
      }
      requestAnimationFrame(() => window.scrollTo(scrollX, scrollY));
    } catch (error) {
      if (error?.name === "AbortError") return;
      if (latestLoads.get(key) === token) window.location.href = href;
    } finally {
      window.clearTimeout(busyTimer);
      if (latestLoads.get(key) === token) {
        currentTargets.forEach((node) => node.removeAttribute("aria-busy"));
        if (loadControllers.get(key) === controller) loadControllers.delete(key);
      }
    }
  }

  function pageSizeHref(select) {
    const value = String(select.value || "").trim();
    if (/^(?:https?:\/\/|\/|\?)/i.test(value)) {
      return new URL(value, window.location.href).toString();
    }
    const url = new URL(window.location.href);
    url.searchParams.set(select.dataset.ajaxPageParam || select.name || "page_size", value);
    (select.dataset.ajaxResetParams || "page")
      .split(",")
      .map((name) => name.trim())
      .filter(Boolean)
      .forEach((name) => url.searchParams.delete(name));
    if (select.dataset.ajaxHash) url.hash = select.dataset.ajaxHash;
    return url.toString();
  }

  function filterHref(form) {
    const url = new URL(form.action || window.location.href, window.location.href);
    url.search = "";
    new FormData(form).forEach((value, name) => {
      if (typeof value === "string") url.searchParams.append(name, value);
    });
    (form.dataset.ajaxResetParams || "page")
      .split(",")
      .map((name) => name.trim())
      .filter(Boolean)
      .forEach((name) => url.searchParams.delete(name));
    if (form.dataset.ajaxHash) url.hash = form.dataset.ajaxHash;
    return url.toString();
  }

  function submitFilter(form, immediate = false) {
    window.clearTimeout(Number(form.dataset.ajaxFilterTimer || 0));
    const run = () => {
      form.dataset.ajaxFilterTimer = "0";
      void load(filterHref(form), form, { history: "replace" });
    };
    if (immediate) run();
    else {
      const delay = Math.max(100, Number(form.dataset.ajaxFilterDelay || 350));
      form.dataset.ajaxFilterTimer = String(window.setTimeout(run, delay));
    }
  }

  function markActiveLink(nav, activeLink) {
    nav.querySelectorAll("a[href]").forEach((link) => {
      const active = link === activeLink;
      link.classList.toggle("active", active);
      if (active) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    });
  }

  document.addEventListener("click", (event) => {
    const link = event.target.closest("[data-ajax-nav] a[href]");
    if (!link || link.classList.contains("disabled") || link.getAttribute("aria-disabled") === "true") return;
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button === 1) return;
    const nav = link.closest("[data-ajax-nav]");
    const href = link.getAttribute("href") || "";
    if (!nav || !href || href.startsWith("#")) return;
    event.preventDefault();
    markActiveLink(nav, link);
    void load(href, nav);
  });

  document.addEventListener("submit", (event) => {
    const form = event.target.closest?.("form[data-ajax-filter]");
    if (!form) return;
    event.preventDefault();
    submitFilter(form, true);
  });

  document.addEventListener("input", (event) => {
    const form = event.target.closest?.("form[data-ajax-filter]");
    if (!form || event.target instanceof HTMLSelectElement) return;
    submitFilter(form, false);
  });

  document.addEventListener("change", (event) => {
    const select = event.target.closest?.("select[data-ajax-page-size]");
    if (select) {
      event.preventDefault();
      event.stopPropagation();
      void load(pageSizeHref(select), select);
      return;
    }
    const form = event.target.closest?.("form[data-ajax-filter]");
    if (form) submitFilter(form, true);
  }, true);

  ["pointerdown", "mouseover", "focusin"].forEach((eventName) => {
    document.addEventListener(eventName, (event) => {
      const link = event.target.closest?.("[data-ajax-nav] a[href]");
      if (link && !link.classList.contains("disabled")) prefetch(link.href);
    });
  });

  window.addEventListener("popstate", (event) => {
    const config = event.state?.ajaxSection;
    if (config?.targets?.length) {
      void load(window.location.href, null, { config, history: false });
    }
  });

  window.UPOSAjaxSections = { load, prefetch };
})();

/* source: password-toggle.js */
(function () {
  function bind(wrap) {
    var input = wrap.querySelector(".pwd-input");
    var btn = wrap.querySelector(".pwd-toggle");
    if (!input || !btn || btn.dataset.bound) return;
    btn.dataset.bound = "1";
    var labelShow = btn.getAttribute("data-label-show") || "Показать пароль";
    var labelHide = btn.getAttribute("data-label-hide") || "Скрыть пароль";
    btn.addEventListener("click", function () {
      var show = input.type === "password";
      input.type = show ? "text" : "password";
      btn.setAttribute("aria-pressed", show ? "true" : "false");
      btn.setAttribute("aria-label", show ? labelHide : labelShow);
    });
  }

  function init() {
    document.querySelectorAll(".pwd-wrap").forEach(bind);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

/* source: instant-navigation.js */
/* Prepare likely same-origin destinations before activation and acknowledge input instantly. */
(() => {
  "use strict";

  const BLOCKED_PATH_PREFIXES = [
    "/api/",
    "/auth",
    "/billing",
    "/admin",
    "/static/",
    "/installer",
  ];
  const TRANSIENT_PARAMS = new Set([
    "err",
    "error",
    "msg",
    "perf_refresh",
    "saved_id",
  ]);
  const TARGET_SELECTOR = [
    "a[href]",
    "[data-workspace-navigate-href]",
    "[data-workspace-tab-href]",
    "[data-workspace-sync-url]",
  ].join(",");
  const pendingTimers = new WeakMap();
  const warmAttempts = new Map();
  const WARM_DEDUPE_MS = 15_000;
  let hoverTimer = 0;
  const recentRoutesKey = "upos:instant-navigation:recent:v1";

  function destination(target) {
    if (!target) return null;
    const value =
      target.dataset?.workspaceNavigateHref ||
      target.dataset?.workspaceTabHref ||
      target.dataset?.workspaceSyncUrl ||
      target.getAttribute?.("href") ||
      "";
    if (!value || value.startsWith("#")) return null;
    try {
      const url = new URL(value, window.location.href);
      if (url.origin !== window.location.origin) return null;
      if (url.protocol !== "http:" && url.protocol !== "https:") return null;
      if (BLOCKED_PATH_PREFIXES.some((prefix) => url.pathname.startsWith(prefix))) return null;
      TRANSIENT_PARAMS.forEach((name) => url.searchParams.delete(name));
      if (
        url.pathname === window.location.pathname &&
        url.search === window.location.search &&
        url.hash === window.location.hash
      ) {
        return null;
      }
      url.hash = "";
      return url;
    } catch {
      return null;
    }
  }

  function eligibleLink(link) {
    if (!(link instanceof HTMLAnchorElement)) return false;
    if (link.hasAttribute("download") || link.target || link.relList.contains("external")) return false;
    if (link.dataset.noInstantNavigation === "1") return false;
    return Boolean(destination(link));
  }

  function markEligible(root = document) {
    root.querySelectorAll?.("a[href]").forEach((link) => {
      if (eligibleLink(link)) {
        link.dataset.instantNavigation = "1";
      } else {
        delete link.dataset.instantNavigation;
      }
    });
  }

  function requestWarm(url) {
    if (!url) return Promise.resolve(false);
    const lastAttempt = warmAttempts.get(url.href) || 0;
    if (Date.now() - lastAttempt < WARM_DEDUPE_MS) return Promise.resolve(true);
    warmAttempts.set(url.href, Date.now());

    const workspaceWarmup = window.UPOSWorkspaceWarmup;
    if (workspaceWarmup?.warm) {
      return Promise.resolve(workspaceWarmup.warm(url.href));
    }

    return fetch(url.href, {
      cache: "default",
      credentials: "same-origin",
      headers: { Accept: "text/html", "X-UPOS-Prefetch": "1" },
      priority: "high",
    }).then((response) => response.ok).catch(() => false);
  }

  function scheduleWarm(target, delayMs = 0) {
    window.clearTimeout(hoverTimer);
    const url = destination(target);
    if (!url) return;
    hoverTimer = window.setTimeout(() => void requestWarm(url), delayMs);
  }

  function interactionTarget(event) {
    return event.target.closest?.(TARGET_SELECTOR) || null;
  }

  function showPending(target) {
    if (!target) return;
    const prior = pendingTimers.get(target);
    if (prior) window.clearTimeout(prior);
    target.classList.add("instant-navigation-target", "is-navigation-pending");
    target.setAttribute("aria-busy", "true");
    const timer = window.setTimeout(() => {
      target.classList.remove("is-navigation-pending");
      target.removeAttribute("aria-busy");
      pendingTimers.delete(target);
    }, 2200);
    pendingTimers.set(target, timer);
  }

  function rememberCurrentRoute() {
    let recent = [];
    try {
      recent = JSON.parse(window.sessionStorage.getItem(recentRoutesKey) || "[]");
    } catch {
      recent = [];
    }
    const current = new URL(window.location.href);
    current.hash = "";
    TRANSIENT_PARAMS.forEach((name) => current.searchParams.delete(name));
    const currentHref = current.href;
    const previous = recent.find((href) => href && href !== currentHref) || "";
    const next = [currentHref, ...recent.filter((href) => href && href !== currentHref)].slice(0, 4);
    try {
      window.sessionStorage.setItem(recentRoutesKey, JSON.stringify(next));
    } catch {
      // Navigation still works when browser storage is unavailable.
    }
    return previous;
  }

  function initialize() {
    markEligible();
    const previousRoute = rememberCurrentRoute();
    if (previousRoute) {
      const warmPrevious = () => window.setTimeout(() => void requestWarm(new URL(previousRoute)), 180);
      window.addEventListener("upos:workspace-warmed", warmPrevious, { once: true });
      window.setTimeout(warmPrevious, 1600);
    }

    const observer = new MutationObserver((records) => {
      records.forEach((record) => {
        record.addedNodes.forEach((node) => {
          if (!(node instanceof Element)) return;
          if (node.matches?.("a[href]") && eligibleLink(node)) {
            node.dataset.instantNavigation = "1";
          }
          markEligible(node);
        });
      });
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });

    document.addEventListener("pointerover", (event) => {
      scheduleWarm(interactionTarget(event));
    }, { capture: true, passive: true });

    document.addEventListener("focusin", (event) => {
      scheduleWarm(interactionTarget(event), 0);
    }, { capture: true, passive: true });

    document.addEventListener("pointerdown", (event) => {
      const target = interactionTarget(event);
      window.clearTimeout(hoverTimer);
      void requestWarm(destination(target));
      showPending(target);
    }, { capture: true, passive: true });

    document.addEventListener(
      "submit",
      (event) => {
        const form = event.target;
        if (!(form instanceof HTMLFormElement)) return;
        const submitter = event.submitter || form.querySelector("[type='submit']");
        showPending(submitter || form);
      },
      true
    );
  }

  window.UPOSInstantNavigation = {
    warm: (value) => requestWarm(destination({ getAttribute: () => String(value || "") })),
    prerender: (value) => requestWarm(destination({ getAttribute: () => String(value || "") })),
  };

  if (document.prerendering) {
    document.addEventListener("prerenderingchange", initialize, { once: true });
  } else {
    initialize();
  }
})();

/* source: app-warmup.js */
/* Warm every accessible workspace route after login and keep it warm. */
(() => {
  "use strict";

  const CACHEABLE_PATHS = new Set([
    "/", "/dashboard", "/finance", "/sales", "/products", "/warehouse",
    "/clients", "/crm", "/suppliers", "/telephony", "/messengers", "/reports",
    "/schet", "/kassa", "/settings", "/organizations", "/organizations/kassa",
    "/organizations/schet", "/organizations/reports", "/organizations/settings",
    "/organizations/users", "/organizations/shipments", "/shipments", "/earnings",
    "/employees",
  ]);
  const ROUTE_LABELS = {
    "/": "Главная", "/dashboard": "Дашборд", "/finance": "Финансы",
    "/sales": "Продажи", "/products": "Товары", "/warehouse": "Склад",
    "/clients": "Клиенты", "/crm": "CRM", "/suppliers": "Поставщики",
    "/telephony": "Телефония", "/messengers": "Мессенджеры", "/reports": "Отчёты",
    "/schet": "Счета", "/kassa": "Касса", "/settings": "Настройки",
    "/organizations": "Организации", "/organizations/kassa": "Касса",
    "/organizations/schet": "Счета", "/organizations/reports": "Отчёты",
    "/organizations/settings": "Настройки", "/organizations/users": "Сотрудники",
    "/organizations/shipments": "Доставка", "/shipments": "Доставка",
    "/earnings": "Начисления", "/employees": "Сотрудники",
  };
  const WARMUP_PRIORITY = new Map([
    ["/reports", 0],
    ["/warehouse", 1],
    ["/products", 2],
    ["/sales", 3],
    ["/clients", 4],
    ["/crm", 5],
    ["/finance", 6],
    ["/dashboard", 7],
    ["/telephony", 8],
    ["/messengers", 9],
    ["/settings", 10],
  ]);
  const TRANSIENT_PARAMS = new Set([
    "err", "error", "msg", "perf_refresh", "saved_id",
  ]);
  const REQUEST_TIMEOUT_MS = 25_000;
  const DONE_TTL_MS = 7 * 60 * 1000;
  const LOADING_TTL_MS = 35_000;
  const MIN_BLOCK_MS = 5_000;
  const MAX_BLOCK_MS = 10_000;
  const REFRESH_DELAY_MS = DONE_TTL_MS + 15_000;
  const inFlight = new Map();
  const warmedAssets = new Set();
  const root = document.documentElement;
  const runtimeVersion = (() => {
    try {
      return new URL(document.currentScript?.src || window.location.href).searchParams.get("v") || "0";
    } catch {
      return "0";
    }
  })();
  const cacheGeneration = root.dataset.uposCacheGeneration || "0";
  const sessionScope = root.dataset.uposSessionScope || document.body.dataset.userId || "workspace";
  const generalScope = window.location.pathname === "/organizations" ||
    window.location.pathname.startsWith("/organizations/");
  const routeScope = generalScope ? "general" : "workspace";
  const stateKey = `upos:page-warmup:v13:${runtimeVersion}:${sessionScope}:${routeScope}:${cacheGeneration}`;
  const readyKey = `upos:workspace-ready:v5:${runtimeVersion}:${sessionScope}:${routeScope}:${cacheGeneration}`;
  const connection = navigator.connection;
  const constrained = Boolean(
    connection?.saveData || /(^|-)2g$/.test(connection?.effectiveType || "") ||
    /3g/.test(connection?.effectiveType || "") || Number(navigator.deviceMemory || 8) <= 4
  );
  const maxConcurrency = constrained ? 1 : 3;
  const navigationCacheKey = `${runtimeVersion}-${sessionScope}-${cacheGeneration}`;
  let rewarmTimer = 0;
  let warmupSuspendedUntil = 0;

  function clearWarmupState() {
    try {
      localStorage.removeItem(stateKey);
    } catch {
      /* Navigation caching still invalidates without sessionStorage. */
    }
  }

  function sendNavigationCacheConfig(timeoutMs = 2000) {
    const controller = navigator.serviceWorker?.controller;
    if (!controller || typeof MessageChannel !== "function") return Promise.resolve(false);
    return new Promise((resolve) => {
      const channel = new MessageChannel();
      let settled = false;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        window.clearTimeout(timeout);
        channel.port1.onmessage = null;
        resolve(value);
      };
      const timeout = window.setTimeout(() => finish(false), timeoutMs);
      channel.port1.onmessage = (event) => finish(Boolean(event.data?.ok));
      controller.postMessage({
        type: "UPOS_ROUTE_CACHE_CONFIG",
        key: navigationCacheKey,
      }, [channel.port2]);
    });
  }

  function waitForServiceWorkerController(timeoutMs = 2500) {
    if (navigator.serviceWorker?.controller) return Promise.resolve(true);
    return new Promise((resolve) => {
      let settled = false;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        navigator.serviceWorker?.removeEventListener("controllerchange", onControllerChange);
        resolve(value);
      };
      const onControllerChange = () => finish(Boolean(navigator.serviceWorker?.controller));
      navigator.serviceWorker?.addEventListener("controllerchange", onControllerChange);
      window.setTimeout(() => finish(Boolean(navigator.serviceWorker?.controller)), timeoutMs);
    });
  }

  async function setupNavigationCache() {
    if (!("serviceWorker" in navigator) || !sessionScope) return false;
    try {
      await navigator.serviceWorker.register(
        `/static/workspace-navigation-sw.js?v=10`,
        { scope: "/", updateViaCache: "none" }
      );
      await navigator.serviceWorker.ready;
      const controlled = await waitForServiceWorkerController();
      if (!controlled) return false;
      return await sendNavigationCacheConfig();
    } catch {
      return false;
    }
  }

  navigator.serviceWorker?.addEventListener("message", (event) => {
    if (event.data?.type !== "UPOS_ROUTE_CACHE_INVALIDATED") return;
    clearWarmupState();
    window.clearTimeout(rewarmTimer);
    rewarmTimer = window.setTimeout(() => {
      void backgroundWarmup({ force: true, priority: "low" });
    }, 600);
  });

  function readJson(key) {
    try {
      const value = JSON.parse(localStorage.getItem(key) || "{}");
      return value && typeof value === "object" ? value : {};
    } catch {
      return {};
    }
  }

  function writeJson(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      /* Storage can be unavailable in hardened browser modes. */
    }
  }

  function storageValue(key) {
    try {
      return sessionStorage.getItem(key) || "";
    } catch {
      return "";
    }
  }

  function setStorageValue(key, value) {
    try {
      sessionStorage.setItem(key, value);
    } catch {
      /* The warmup still works without persisted client state. */
    }
  }

  function stateFresh(url) {
    const entry = readJson(stateKey)[url];
    if (!entry || !entry.at) return false;
    const ttl = entry.status === "done" ? DONE_TTL_MS : LOADING_TTL_MS;
    return Date.now() - Number(entry.at) < ttl;
  }

  function setState(url, status) {
    const state = readJson(stateKey);
    if (!status) delete state[url];
    else state[url] = { at: Date.now(), status };
    const cutoff = Date.now() - DONE_TTL_MS * 2;
    Object.keys(state).forEach((key) => {
      if (Number(state[key]?.at || 0) < cutoff) delete state[key];
    });
    writeJson(stateKey, state);
  }

  function canonicalUrl(value) {
    try {
      const url = new URL(value, window.location.href);
      if (url.origin !== window.location.origin || !CACHEABLE_PATHS.has(url.pathname)) return null;
      TRANSIENT_PARAMS.forEach((name) => url.searchParams.delete(name));
      url.hash = "";
      return url.toString();
    } catch {
      return null;
    }
  }

  function canonicalLink(link) {
    return canonicalUrl(link?.href || "");
  }

  function canonicalRouteLink(link) {
    if (!link) return null;
    const baseHref = link.dataset.workspaceBaseHref || link.getAttribute("href") || link.href;
    try {
      const url = new URL(baseHref, window.location.href);
      if (url.origin !== window.location.origin || !CACHEABLE_PATHS.has(url.pathname)) return null;
      url.search = "";
      url.hash = "";
      return url.toString();
    } catch {
      return null;
    }
  }

  function accessibleUrls() {
    const selector = generalScope
      ? "a.nav-link[href], a.nav-sublink[href]"
      : "#app-sidebar a.nav-link[href], #app-sidebar a.nav-sublink[href]";
    const links = Array.from(document.querySelectorAll(selector));
    // Warm the stable module entry first, then the remembered working tab. This keeps
    // a stale client/document URL from delaying every other module at login while
    // preserving the existing "return to the last open tab" behavior.
    const urls = [
      ...links.map((link) => canonicalRouteLink(link)),
      ...links.map((link) => canonicalLink(link)),
    ].filter(Boolean);
    const current = canonicalUrl(window.location.href);
    return [...new Set(urls)]
      .filter((url) => url !== current)
      .sort((left, right) => {
        const leftUrl = new URL(left);
        const rightUrl = new URL(right);
        const leftPriority = WARMUP_PRIORITY.get(leftUrl.pathname) ?? 100;
        const rightPriority = WARMUP_PRIORITY.get(rightUrl.pathname) ?? 100;
        if (leftPriority !== rightPriority) return leftPriority - rightPriority;
        if (leftUrl.pathname !== rightUrl.pathname) {
          return leftUrl.pathname.localeCompare(rightUrl.pathname);
        }
        return leftUrl.search.length - rightUrl.search.length;
      });
  }

  function assetUrls(html, pageUrl) {
    const parsed = new DOMParser().parseFromString(html, "text/html");
    return Array.from(parsed.querySelectorAll('link[rel="stylesheet"][href], script[src]'))
      .map((node) => node.getAttribute("href") || node.getAttribute("src") || "")
      .map((value) => {
        try {
          return new URL(value, pageUrl).toString();
        } catch {
          return "";
        }
      })
      .filter((value) => value.startsWith(`${window.location.origin}/static/`));
  }

  async function warmAsset(url) {
    if (!url || warmedAssets.has(url)) return;
    warmedAssets.add(url);
    try {
      await fetch(url, { cache: "force-cache", credentials: "same-origin", priority: "low" });
    } catch {
      warmedAssets.delete(url);
    }
  }

  function warm(url, options = {}) {
    const { force = false, priority = "low" } = options;
    if (!url || (!force && stateFresh(url))) return Promise.resolve(true);
    const existing = inFlight.get(url);
    if (existing) {
      if (priority === "high" && existing.priority !== "high") {
        existing.controller.abort();
        inFlight.delete(url);
        setState(url, "");
      } else {
        return existing.promise;
      }
    }

    const controller = new AbortController();
    let entry = null;
    const task = (async () => {
      setState(url, "loading");
      const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
      try {
        const response = await fetch(url, {
          cache: force ? "reload" : "default",
          credentials: "same-origin",
          headers: { Accept: "text/html", "X-UPOS-Prefetch": "1" },
          priority,
          signal: controller.signal,
        });
        if (!response.ok) throw new Error(`Warmup failed: ${response.status}`);
        const requestedUrl = new URL(url);
        const finalUrl = new URL(response.url, window.location.href);
        if (response.redirected && finalUrl.pathname !== requestedUrl.pathname) {
          throw new Error(`Warmup redirected to ${finalUrl.pathname}`);
        }
        const html = await response.text();
        await Promise.all(assetUrls(html, url).map(warmAsset));
        if (inFlight.get(url) === entry) setState(url, "done");
        return true;
      } catch {
        if (inFlight.get(url) === entry) setState(url, "");
        return false;
      } finally {
        window.clearTimeout(timeout);
      }
    })();
    entry = { controller, priority, promise: task };
    inFlight.set(url, entry);
    task.finally(() => {
      if (inFlight.get(url) === entry) inFlight.delete(url);
    });
    return task;
  }

  async function warmQueue(urls, options = {}) {
    const unique = [...new Set(urls)].filter(Boolean);
    let cursor = 0;
    let completed = 0;
    let succeeded = 0;

    async function worker() {
      while (cursor < unique.length) {
        if (options.priority !== "high" && Date.now() < warmupSuspendedUntil) {
          await delay(Math.min(2500, warmupSuspendedUntil - Date.now()));
        }
        const index = cursor;
        cursor += 1;
        const url = unique[index];
        options.onStart?.(url, index, unique.length);
        const ok = await warm(url, options);
        completed += 1;
        if (ok) succeeded += 1;
        options.onProgress?.({ completed, succeeded, total: unique.length, url, ok });
      }
    }

    await Promise.all(
      Array.from({ length: Math.min(maxConcurrency, Math.max(1, unique.length)) }, worker)
    );
    return { completed, succeeded, total: unique.length };
  }

  function delay(ms) {
    return new Promise((resolve) => window.setTimeout(resolve, ms));
  }

  function idle(callback, timeout = 1200) {
    if ("requestIdleCallback" in window) window.requestIdleCallback(callback, { timeout });
    else window.setTimeout(callback, Math.min(timeout, 500));
  }

  function createOverlay(total) {
    const overlay = document.createElement("div");
    overlay.className = "workspace-warmup";
    overlay.setAttribute("role", "status");
    overlay.setAttribute("aria-live", "polite");
    overlay.innerHTML = `
      <section class="workspace-warmup-panel">
        <div class="workspace-warmup-brand">UPOS</div>
        <h1>Загружается рабочее пространство</h1>
        <p data-workspace-warmup-status>Подготавливаем основные разделы</p>
        <div class="workspace-warmup-track" aria-hidden="true">
          <span data-workspace-warmup-progress></span>
        </div>
        <small data-workspace-warmup-count>0 из ${total}</small>
      </section>`;
    document.body.appendChild(overlay);
    requestAnimationFrame(() => overlay.classList.add("is-visible"));
    return overlay;
  }

  function updateOverlay(overlay, payload) {
    if (!overlay) return;
    const total = Math.max(1, payload.total);
    const percent = Math.min(100, Math.round((payload.completed / total) * 100));
    const path = payload.url ? new URL(payload.url).pathname : "";
    const label = ROUTE_LABELS[path] || "Рабочее пространство";
    const status = overlay.querySelector("[data-workspace-warmup-status]");
    const progress = overlay.querySelector("[data-workspace-warmup-progress]");
    const count = overlay.querySelector("[data-workspace-warmup-count]");
    if (status) status.textContent = payload.completed >= payload.total
      ? "Рабочее пространство готово" : `Подготавливаем: ${label}`;
    if (progress) progress.style.width = `${percent}%`;
    if (count) count.textContent = `${payload.completed} из ${payload.total}`;
  }

  async function blockingWarmup(urls) {
    const overlay = createOverlay(urls.length);
    const startedAt = performance.now();
    const queue = warmQueue(urls, {
      priority: "high",
      onStart: (url, index, total) => updateOverlay(overlay, { completed: index, total, url }),
      onProgress: (payload) => updateOverlay(overlay, payload),
    });
    const completedQueue = queue.then((result) => {
      if (result.succeeded === result.total) setStorageValue(readyKey, "1");
      window.dispatchEvent(new CustomEvent("upos:workspace-warmed", {
        detail: {
          ...result,
          durationMs: Math.round(performance.now() - startedAt),
        },
      }));
      return result;
    });
    await Promise.race([
      Promise.all([completedQueue, delay(MIN_BLOCK_MS)]),
      delay(MAX_BLOCK_MS),
    ]);
    overlay.classList.remove("is-visible");
    window.setTimeout(() => overlay.remove(), 220);
    void completedQueue;
  }

  function backgroundWarmup(options = {}) {
    const urls = accessibleUrls();
    if (!urls.length) return Promise.resolve({ completed: 0, succeeded: 0, total: 0 });
    return warmQueue(urls, options);
  }

  function prioritizeUserNavigation() {
    warmupSuspendedUntil = Date.now() + 3000;
    inFlight.forEach((entry, url) => {
      if (entry.priority === "high") return;
      entry.controller.abort();
      inFlight.delete(url);
      setState(url, "");
    });
  }

  function scheduleRefresh() {
    window.setTimeout(() => {
      if (document.visibilityState === "visible") {
        void backgroundWarmup({ force: true, priority: "low" });
      }
      scheduleRefresh();
    }, REFRESH_DELAY_MS);
  }

  ["pointerover", "focusin"].forEach((eventName) => {
    document.addEventListener(eventName, (event) => {
      const link = event.target.closest?.("a[href]");
      const url = canonicalLink(link);
      if (url) void warm(url, { priority: "auto" });
    }, { capture: true, passive: true });
  });

  document.addEventListener("pointerdown", (event) => {
    const link = event.target.closest?.("a[href]");
    if (!canonicalLink(link)) return;
    prioritizeUserNavigation();
  }, { capture: true, passive: true });

  document.addEventListener("submit", prioritizeUserNavigation, { capture: true });

  async function start() {
    const urls = accessibleUrls();
    // A ready marker belongs to one concrete app bundle/runtime version. Rebuilds
    // must perform one genuine warmup even when the server-side login flag was
    // already consumed by an older page in the same authenticated session.
    const requiresBlocking = storageValue(readyKey) !== "1";
    await setupNavigationCache();
    if (requiresBlocking) await blockingWarmup(urls);
    else if (!connection?.saveData) idle(() => void backgroundWarmup(), 300);
    scheduleRefresh();
  }

  window.UPOSWorkspaceWarmup = {
    refresh: () => backgroundWarmup({ force: true, priority: "high" }),
    warm: (value) => warm(canonicalUrl(value), { priority: "high" }),
  };

  if (document.prerendering) {
    document.addEventListener("prerenderingchange", () => void start(), { once: true });
  } else if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => void start(), { once: true });
  } else {
    void start();
  }
})();

/* source: messenger-notifications.js */
(function () {
  var REFRESH_MS = 4000;
  var LEADER_TTL_MS = 12000;
  var MIN_REQUEST_GAP_MS = 2000;
  var RESUME_DEBOUNCE_MS = 180;
  var LEADER_KEY = "upos:messenger-notifications:leader";
  var PAYLOAD_KEY = "upos:messenger-notifications:payload";
  var TAB_ID = String(Date.now()) + ":" + Math.random().toString(36).slice(2);
  var channel = typeof BroadcastChannel === "function"
    ? new BroadcastChannel("upos-messenger-notifications")
    : null;

  function readStored(key) {
    try { return JSON.parse(localStorage.getItem(key) || "null"); }
    catch (_error) { return null; }
  }

  function isForegroundTab() {
    return document.visibilityState !== "hidden" &&
      (typeof document.hasFocus !== "function" || document.hasFocus());
  }

  function claimLeadership(force) {
    var now = Date.now();
    var current = readStored(LEADER_KEY);
    if (!force && current && current.id !== TAB_ID && Number(current.expires || 0) > now) return false;
    try {
      localStorage.setItem(LEADER_KEY, JSON.stringify({ id: TAB_ID, expires: now + LEADER_TTL_MS }));
      var confirmed = readStored(LEADER_KEY);
      return Boolean(confirmed && confirmed.id === TAB_ID);
    } catch (_error) {
      return document.visibilityState !== "hidden";
    }
  }

  function publish(payload) {
    var packet = { at: Date.now(), payload: payload };
    if (channel) channel.postMessage(packet);
    try { localStorage.setItem(PAYLOAD_KEY, JSON.stringify(packet)); } catch (_error) {}
  }

  function escapeHtml(value) {
    return String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function journalUrl(row) {
    var params = new URLSearchParams();
    if (row.channel) params.set("journal_channel", row.channel);
    if (row.contact) params.set("journal_q", row.contact);
    var query = params.toString();
    return "/messengers" + (query ? "?" + query : "") + "#sms_journal";
  }

  function createModal() {
    var dialog = document.createElement("dialog");
    dialog.className = "sidebar-messenger-modal";
    dialog.innerHTML =
      '<section class="sidebar-messenger-modal-surface"><header class="sidebar-messenger-modal-head">' +
      '<div><h2>Сообщения новых лидов</h2><p data-messenger-modal-summary>Только непрочитанные</p></div>' +
      '<button type="button" class="settings-profile-modal-close" data-messenger-modal-close aria-label="Закрыть">×</button>' +
      '</header><div class="sidebar-messenger-modal-list" data-messenger-modal-list></div>' +
      '<footer class="sidebar-messenger-modal-foot"><a class="btn btn-secondary" href="/messengers#inbox">Все диалоги</a>' +
      '<a class="btn btn-secondary" href="/messengers#sms_journal">Журнал сообщений</a>' +
      '<button type="button" class="btn" data-messenger-modal-close>Закрыть</button></footer></section>';
    dialog.addEventListener("click", function (event) { if (event.target === dialog) dialog.close(); });
    dialog.querySelectorAll("[data-messenger-modal-close]").forEach(function (button) {
      button.addEventListener("click", function () { dialog.close(); });
    });
    document.body.appendChild(dialog);
    return dialog;
  }

  function renderList(list, rows) {
    if (!rows.length) {
      list.innerHTML = '<div class="sidebar-messenger-empty">Новых сообщений от новых лидов пока нет.</div>';
      return;
    }
    list.innerHTML = rows.map(function (row) {
      var unread = Number(row.unread || 0);
      return '<a class="sidebar-messenger-row" href="' + escapeHtml(journalUrl(row)) + '">' +
        '<span class="sidebar-messenger-channel">' + escapeHtml(row.channel || "Чат") + '</span>' +
        '<span class="sidebar-messenger-row-main"><strong>' + escapeHtml(row.contact || "Клиент") + '</strong><small>' + escapeHtml(row.message || "") + '</small></span>' +
        '<span class="sidebar-messenger-row-side">' + (row.time_label ? '<time>' + escapeHtml(row.time_label) + '</time>' : '') +
        (unread ? '<b>' + unread + '</b>' : '') + '</span></a>';
    }).join("");
  }

  function boot() {
    var button = document.querySelector("[data-sidebar-messenger-notifications]");
    if (!button) return;
    var rows = [];
    var modal = null;
    var refreshPromise = null;
    var lastRequestAt = 0;
    var resumeTimer = 0;

    function apply(payload) {
      rows = Array.isArray(payload.notifications)
        ? payload.notifications.filter(function (row) { return Number(row.unread || 0) > 0; })
        : rows;
      var unread = Number(payload.unread_total || 0);
      var status = button.querySelector("[data-sidebar-messenger-status]");
      var count = button.querySelector("[data-sidebar-messenger-count]");
      if (status) status.textContent = unread > 0 ? "Новые сообщения: " + unread : "Нет новых";
      if (count) { count.hidden = unread <= 0; count.textContent = String(unread); }
      button.dataset.state = unread > 0 ? "new" : "idle";
      if (modal && modal.open) renderList(modal.querySelector("[data-messenger-modal-list]"), rows);
    }

    function refresh(force) {
      if (!isForegroundTab()) return Promise.resolve();
      if (refreshPromise) return refreshPromise;
      var now = Date.now();
      if (now - lastRequestAt < MIN_REQUEST_GAP_MS) return Promise.resolve();
      if (!claimLeadership(false)) return Promise.resolve();
      lastRequestAt = now;
      refreshPromise = fetch("/api/messengers/notifications", { credentials: "same-origin", headers: { Accept: "application/json" } })
        .then(function (response) { if (!response.ok) throw new Error(); return response.json(); })
        .then(function (payload) {
          apply(payload);
          publish(payload);
        })
        .catch(function () {
          var status = button.querySelector("[data-sidebar-messenger-status]");
          if (status) status.textContent = "Не удалось обновить";
        })
        .finally(function () {
          refreshPromise = null;
        });
      return refreshPromise;
    }

    function scheduleResumeRefresh() {
      window.clearTimeout(resumeTimer);
      resumeTimer = window.setTimeout(function () { refresh(true); }, RESUME_DEBOUNCE_MS);
    }

    button.addEventListener("click", function () {
      if (!modal) modal = createModal();
      renderList(modal.querySelector("[data-messenger-modal-list]"), rows);
      modal.querySelector("[data-messenger-modal-summary]").textContent = rows.length
        ? "Только непрочитанные"
        : "Новых сообщений от новых лидов нет";
      modal.showModal();
      refresh(true);
    });

    function acceptPacket(packet) {
      if (packet && packet.payload) apply(packet.payload);
    }
    if (channel) channel.addEventListener("message", function (event) { acceptPacket(event.data); });
    window.addEventListener("storage", function (event) {
      if (event.key === PAYLOAD_KEY && event.newValue) acceptPacket(readStored(PAYLOAD_KEY));
    });
    var saved = readStored(PAYLOAD_KEY);
    if (saved && Date.now() - Number(saved.at || 0) < LEADER_TTL_MS) {
      acceptPacket(saved);
      lastRequestAt = Number(saved.at || 0);
    }

    refresh();
    window.setInterval(refresh, REFRESH_MS);
    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "visible") scheduleResumeRefresh();
    });
    window.addEventListener("focus", scheduleResumeRefresh);
  }

  function start() {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", boot, { once: true });
    } else {
      boot();
    }
  }

  if (document.prerendering) {
    document.addEventListener("prerenderingchange", start, { once: true });
  } else {
    start();
  }
})();

/* source: floating-phone.js */
/* Плавающий телефон: звонок прямо из браузера.
 *
 * Раньше виджет только отдавал номер десктопному мосту UposSip на
 * 127.0.0.1:5058. На телефоне и в обычном браузере такого моста нет, и вызов
 * навсегда оставался в статусе «Отправляю вызов в SIP…». Теперь звоним через
 * WebRTC (JsSIP по SIP-over-WSS) тем же модулем, что и приложение
 * установщика, а мост и набор через SIM остаются запасными путями.
 *
 * Для приёма входящих JsSIP регистрируется автоматически после загрузки страницы.
 */
(() => {
  "use strict";

  const root = document.querySelector("[data-floating-phone]");
  if (!root) return;

  const toggle = root.querySelector("[data-floating-phone-toggle]");
  const panel = root.querySelector("[data-floating-phone-panel]");
  const close = root.querySelector("[data-floating-phone-close]");
  const head = root.querySelector(".upos-floating-phone-head");
  const form = root.querySelector("[data-floating-phone-form]");
  const input = root.querySelector("[data-floating-phone-input]");
  const providerSelect = root.querySelector("[data-floating-phone-provider]");
  const status = root.querySelector("[data-floating-phone-status]");
  const submitButton = form?.querySelector('button[type="submit"]');
  const hangupButton = root.querySelector("[data-floating-phone-hangup]");
  const incomingPanel = root.querySelector("[data-floating-phone-incoming]");
  const incomingCaller = root.querySelector("[data-floating-phone-caller]");
  const answerButton = root.querySelector("[data-floating-phone-answer]");
  const rejectButton = root.querySelector("[data-floating-phone-reject]");
  const bridgeUrl = root.dataset.floatingPhoneBridge || "http://127.0.0.1:5058/call";

  /* ── Положение и раскрытие панели (поведение прежнее) ───────────────── */

  const storageKey = "upos:floating-phone-position";
  const providerStorageKey = "upos:floating-phone-provider";
  const sipAccountsCacheKey = "upos:floating-phone:sip-accounts:v1";
  const sipAccountsCacheTtlMs = 5 * 60 * 1000;
  const edgeGap = 8;
  const dragGap = 4;
  let dragState = null;
  let ignoreNextToggleClick = false;
  const clamp = (value, min, max) => Math.min(Math.max(value, min), Math.max(min, max));

  const alignPanel = () => {
    if (!panel || panel.hidden) return;
    panel.style.left = "0";
    panel.style.right = "auto";
    panel.style.top = "auto";
    panel.style.bottom = "70px";
    const phoneRect = root.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    if (phoneRect.left + panelRect.width > window.innerWidth - edgeGap) {
      panel.style.left = "auto";
      panel.style.right = "0";
    }
    if (phoneRect.top - panelRect.height < edgeGap) {
      panel.style.top = "70px";
      panel.style.bottom = "auto";
    }
  };

  const applyPosition = (position, save = false) => {
    const rect = root.getBoundingClientRect();
    const maxX = window.innerWidth - rect.width - edgeGap;
    const maxY = window.innerHeight - rect.height - edgeGap;
    const x = clamp(position.x, edgeGap, maxX);
    const y = clamp(position.y, edgeGap, maxY);
    root.style.left = `${x}px`;
    root.style.top = `${y}px`;
    root.style.right = "auto";
    root.style.bottom = "auto";
    root.classList.add("is-positioned");
    alignPanel();
    if (save) {
      try {
        window.localStorage.setItem(storageKey, JSON.stringify({ x, y }));
      } catch (error) {
        // В некоторых режимах браузера localStorage отключён.
      }
    }
  };

  const restorePosition = () => {
    try {
      const saved = JSON.parse(window.localStorage.getItem(storageKey) || "null");
      if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) applyPosition(saved);
    } catch (error) {
      window.localStorage.removeItem(storageKey);
    }
  };

  const openPanel = () => {
    panel.hidden = false;
    toggle.setAttribute("aria-expanded", "true");
    window.requestAnimationFrame(() => {
      alignPanel();
      input?.focus();
    });
    ensureSoftphone();
  };

  const closePanel = () => {
    panel.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
  };

  const startDrag = (event) => {
    if (event.button !== undefined && event.button !== 0) return;
    const target = event.target instanceof Element ? event.target : null;
    if (target?.closest("[data-floating-phone-close], input, a, select, button[type=submit]")) return;
    const rect = root.getBoundingClientRect();
    dragState = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      originX: rect.left,
      originY: rect.top,
      moved: false,
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
  };

  const moveDrag = (event) => {
    if (!dragState || event.pointerId !== dragState.pointerId) return;
    const dx = event.clientX - dragState.startX;
    const dy = event.clientY - dragState.startY;
    if (!dragState.moved && Math.hypot(dx, dy) < dragGap) return;
    dragState.moved = true;
    root.classList.add("is-dragging");
    event.preventDefault();
    applyPosition({ x: dragState.originX + dx, y: dragState.originY + dy });
  };

  const endDrag = (event) => {
    if (!dragState || event.pointerId !== dragState.pointerId) return;
    const wasMoved = dragState.moved;
    dragState = null;
    root.classList.remove("is-dragging");
    if (wasMoved) {
      const rect = root.getBoundingClientRect();
      applyPosition({ x: rect.left, y: rect.top }, true);
      ignoreNextToggleClick = true;
      window.setTimeout(() => {
        ignoreNextToggleClick = false;
      }, 0);
    }
  };

  restorePosition();
  toggle?.addEventListener("pointerdown", startDrag);
  head?.addEventListener("pointerdown", startDrag);
  document.addEventListener("pointermove", moveDrag);
  document.addEventListener("pointerup", endDrag);
  document.addEventListener("pointercancel", endDrag);
  window.addEventListener("resize", () => {
    if (!root.classList.contains("is-positioned")) return;
    const rect = root.getBoundingClientRect();
    applyPosition({ x: rect.left, y: rect.top }, true);
  });
  toggle?.addEventListener("click", (event) => {
    if (ignoreNextToggleClick) {
      event.preventDefault();
      event.stopPropagation();
      ignoreNextToggleClick = false;
      return;
    }
    panel.hidden ? openPanel() : closePanel();
  });
  close?.addEventListener("click", closePanel);
  document.addEventListener("click", (event) => {
    // Во время разговора панель не прячем: из неё кладут трубку.
    if (!panel.hidden && !root.contains(event.target) && !inCall) closePanel();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !inCall) closePanel();
  });

  const setStatus = (message, tone = "ready") => {
    if (!status) return;
    status.dataset.state = tone;
    const dot = status.querySelector("span");
    status.textContent = "";
    if (dot) status.append(dot);
    status.append(document.createTextNode(message));
  };

  /* ── Софтфон ───────────────────────────────────────────────────────── */

  let softphoneReady = null;
  let accounts = [];
  let inCall = false;
  let ringTimer = null;
  let ringContext = null;

  function ringOnce() {
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    try {
      ringContext = ringContext || new AudioContext();
      ringContext.resume().catch(() => {});
      const oscillator = ringContext.createOscillator();
      const gain = ringContext.createGain();
      oscillator.frequency.value = 440;
      gain.gain.setValueAtTime(0.0001, ringContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.12, ringContext.currentTime + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, ringContext.currentTime + 0.38);
      oscillator.connect(gain);
      gain.connect(ringContext.destination);
      oscillator.start();
      oscillator.stop(ringContext.currentTime + 0.4);
    } catch (_error) {
      // Some browsers block sound until the first user interaction; visual ringing remains active.
    }
  }

  function startRinging() {
    stopRinging();
    root.classList.add("is-ringing");
    navigator.vibrate?.([250, 120, 250]);
    ringOnce();
    ringTimer = window.setInterval(ringOnce, 1800);
  }

  function stopRinging() {
    root.classList.remove("is-ringing");
    navigator.vibrate?.(0);
    window.clearInterval(ringTimer);
    ringTimer = null;
  }

  function setIncomingUi(event = null) {
    const active = Boolean(event);
    if (incomingPanel) incomingPanel.hidden = !active;
    if (incomingCaller && active) incomingCaller.textContent = event.name || event.from || "Неизвестный номер";
    if (submitButton) submitButton.disabled = active || inCall;
    if (!active) stopRinging();
  }

  const loadScript = (src) =>
    new Promise((resolve, reject) => {
      if (document.querySelector(`script[data-phone-src="${src}"]`)) return resolve();
      const node = document.createElement("script");
      node.src = src;
      node.dataset.phoneSrc = src;
      node.onload = () => resolve();
      node.onerror = () => reject(new Error(`Не загрузился ${src}`));
      document.head.appendChild(node);
    });

  function accountById(id) {
    return accounts.find((item) => String(item.id) === String(id)) || null;
  }

  // Типовая ошибка настройки: в адресе АТС указан IP. Сертификат выписывают на
  // домен, поэтому браузер рвёт WSS ещё до SIP — и причина никак не видна.
  function looksLikeIpHost(wsUrl) {
    try {
      const host = new URL(String(wsUrl)).hostname;
      return /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.includes(":");
    } catch (error) {
      return false;
    }
  }

  function selectedAccount() {
    const value = providerSelect?.value || "";
    if (!value) return accounts[0] || null;
    return accountById(value);
  }

  function readCachedAccounts() {
    try {
      const cached = JSON.parse(window.sessionStorage.getItem(sipAccountsCacheKey) || "null");
      if (!cached || !Array.isArray(cached.accounts) || !cached.at) return null;
      if (Date.now() - Number(cached.at) >= sipAccountsCacheTtlMs) return null;
      return cached.accounts;
    } catch (_error) {
      return null;
    }
  }

  function cacheAccounts(value) {
    try {
      window.sessionStorage.setItem(sipAccountsCacheKey, JSON.stringify({
        at: Date.now(),
        accounts: value,
      }));
    } catch (_error) {
      // The phone still works when sessionStorage is unavailable.
    }
  }

  async function loadAccounts() {
    const cached = readCachedAccounts();
    if (cached) return cached;
    const response = await fetch("/api/telephony/sip", { credentials: "same-origin" });
    const payload = await response.json().catch(() => ({}));
    const loaded = Array.isArray(payload.accounts) ? payload.accounts : [];
    cacheAccounts(loaded);
    return loaded;
  }

  function fillProviders() {
    if (!providerSelect || !accounts.length) return;
    // Список провайдеров в шаблоне приходит не на каждой странице, поэтому
    // заполняем его из API — иначе в выборе оставалось одно «Авто».
    const previous = providerSelect.value;
    let savedProvider = "";
    try {
      savedProvider = window.localStorage.getItem(providerStorageKey) || "";
    } catch (error) {
      savedProvider = "";
    }
    providerSelect.textContent = "";
    accounts.forEach((account) => {
      const option = document.createElement("option");
      option.value = String(account.id);
      option.textContent = account.label || account.extension || "SIP";
      option.dataset.login = account.extension || "";
      option.dataset.providerName = account.label || account.extension || "SIP";
      providerSelect.append(option);
    });
    const auto = document.createElement("option");
    auto.value = "";
    auto.textContent = "Авто (SIP приложение)";
    auto.dataset.providerName = "Авто";
    providerSelect.append(auto);
    const preferredAccount =
      accountById(savedProvider) ||
      accountById(previous) ||
      accounts.find((account) => /^\d+$/.test(String(account.extension || "").trim())) ||
      accounts[0];
    if (preferredAccount) providerSelect.value = String(preferredAccount.id);
  }

  function connectErrorText(account, error) {
    if (account && looksLikeIpHost(account.ws_url)) {
      return "АТС указана по IP — для WSS нужен домен из сертификата. Проверьте адрес в настройках телефонии";
    }
    const cause = String(error?.message || "");
    const statusCode = Number(error?.statusCode || 0);
    const reasonPhrase = String(error?.reasonPhrase || "").trim();
    const responseDetails = statusCode ? ` (${statusCode}${reasonPhrase ? ` ${reasonPhrase}` : ""})` : "";
    // Rejected — связь с АТС есть, но регистрацию не приняли: дело в
    // SIP-аккаунте (WebRTC не включён или пароль не тот), а не в сети.
    if (/rejected|forbidden|authentication/i.test(cause)) {
      return `АТС отклонила регистрацию${responseDetails} — проверьте SIP-аккаунт и WebRTC. Пока звоним через телефон`;
    }
    return `АТС недоступна (${cause || "ошибка"}) — звоним через телефон`;
  }

  function bindSoftphoneEvents(sip) {
    if (sip.__floatingPhoneBound) return;
    sip.__floatingPhoneBound = true;
    sip.on("registered", () => {
      if (!inCall) setStatus("SIP на связи — можно звонить", "ok");
    });
    sip.on("registrationFailed", (event) => {
      const statusCode = Number(event?.statusCode || 0);
      const reasonPhrase = String(event?.reasonPhrase || "").trim();
      const details = statusCode ? `${statusCode}${reasonPhrase ? ` ${reasonPhrase}` : ""}` : event?.cause || "ошибка";
      setStatus(`АТС отклонила регистрацию (${details}) — звоним через телефон`, "error");
    });
    sip.on("progress", () => setStatus("Идёт вызов…", "pending"));
    sip.on("accepted", () => {
      inCall = true;
      setIncomingUi(null);
      setStatus("Разговор идёт", "ok");
      setCallUi(true);
    });
    sip.on("incoming", (event) => {
      inCall = true;
      panel.hidden = false;
      toggle.setAttribute("aria-expanded", "true");
      setIncomingUi(event || {});
      startRinging();
      window.requestAnimationFrame(alignPanel);
      setStatus(`Входящий: ${event?.name || event?.from || "неизвестный"}`, "pending");
    });
    sip.on("ended", () => {
      inCall = false;
      setIncomingUi(null);
      setStatus("Звонок завершён", "ready");
      setCallUi(false);
    });
    sip.on("failed", (event) => {
      inCall = false;
      setIncomingUi(null);
      setStatus(`Звонок не состоялся: ${event?.cause || "ошибка"}`, "error");
      setCallUi(false);
    });
  }

  function setCallUi(active) {
    if (hangupButton) hangupButton.hidden = !active;
    if (submitButton) submitButton.disabled = active || (incomingPanel && !incomingPanel.hidden);
  }

  function ensureSoftphone() {
    if (softphoneReady) return softphoneReady;
    softphoneReady = (async () => {
      accounts = (await loadAccounts()).filter((item) => item && item.ws_url && item.sip_uri);
      if (!accounts.length) {
        setStatus("SIP-аккаунт не настроен — вызов уйдёт в приложение", "ready");
        return null;
      }
      fillProviders();
      await loadScript("/static/jssip.min.js?v=1");
      await loadScript("/static/installer-softphone.js?v=11");
      const sip = window.UposSoftphone;
      if (!sip || !sip.available()) {
        setStatus("Софтфон не загрузился — вызов уйдёт в приложение", "error");
        return null;
      }
      sip.configure({ audioId: "upos-floating-phone-audio" });
      bindSoftphoneEvents(sip);
      const account = selectedAccount();
      if (!account) return sip;
      setStatus("Подключаюсь к АТС…", "pending");
      try {
        await sip.connect(account);
      } catch (error) {
        // Регистрация не удалась — остаются мост и набор через SIM.
        setStatus(connectErrorText(account, error), "error");
      }
      return sip;
    })().catch((error) => {
      setStatus(`Телефон недоступен: ${error?.message || "ошибка"}`, "error");
      return null;
    });
    return softphoneReady;
  }

  providerSelect?.addEventListener("change", async () => {
    try {
      window.localStorage.setItem(providerStorageKey, providerSelect.value || "");
    } catch (error) {
      // В некоторых режимах браузера localStorage отключён.
    }
    const sip = await ensureSoftphone();
    const account = selectedAccount();
    if (!sip || !account) return;
    setStatus("Подключаюсь к АТС…", "pending");
    try {
      await sip.connect(account);
    } catch (error) {
      setStatus(connectErrorText(account, error), "error");
    }
  });

  hangupButton?.addEventListener("click", () => {
    window.UposSoftphone?.hangup();
    inCall = false;
    setIncomingUi(null);
    setCallUi(false);
    setStatus("Звонок завершён", "ready");
  });

  answerButton?.addEventListener("click", () => {
    if (!window.UposSoftphone?.answer()) return;
    setIncomingUi(null);
    setCallUi(true);
    setStatus("Соединяю разговор…", "pending");
  });

  rejectButton?.addEventListener("click", () => {
    if (typeof window.UposSoftphone?.reject === "function") window.UposSoftphone.reject();
    else window.UposSoftphone?.hangup();
    inCall = false;
    setIncomingUi(null);
    setCallUi(false);
    setStatus("Входящий звонок отклонён", "ready");
  });

  /* ── Набор номера ──────────────────────────────────────────────────── */

  async function callViaBridge(phone) {
    const selected = providerSelect?.selectedOptions?.[0] || null;
    const response = await fetch(bridgeUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        phone,
        provider_id: providerSelect?.value || "",
        provider: selected?.dataset.providerName || "",
        provider_login: selected?.dataset.login || "",
      }),
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || payload.ok === false) {
      throw new Error(payload.error || "SIP-приложение не приняло вызов");
    }
  }

  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const phone = (input?.value || "").trim();
    if (!phone) {
      input?.focus();
      return;
    }
    submitButton?.setAttribute("disabled", "disabled");
    try {
      const sip = await ensureSoftphone();
      // Первый путь — звонок прямо из браузера.
      if (sip && sip.isRegistered() && sip.call(phone)) {
        inCall = true;
        setCallUi(true);
        setStatus("Набираю…", "pending");
        return;
      }
      // Второй — десктопное SIP-приложение на этом же компьютере.
      setStatus("Отправляю вызов в SIP…", "pending");
      try {
        await callViaBridge(phone);
        setStatus("Вызов отправлен в SIP", "ok");
        return;
      } catch (bridgeError) {
        // Третий — набор средствами самого телефона.
        const clean = phone.replace(/[^\d+*#]/g, "");
        if (clean && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
          setStatus("Открываю набор телефона", "ready");
          window.location.href = `tel:${clean}`;
          return;
        }
        setStatus(`Запустите SIP-приложение: ${bridgeError.message || "нет связи"}`, "error");
      }
    } finally {
      if (!inCall) submitButton?.removeAttribute("disabled");
    }
  });

  // A receiver must be registered before the first call arrives, not after the panel is opened.
  const connectWhenForeground = () => {
    if (document.visibilityState === "hidden") return;
    if (typeof document.hasFocus === "function" && !document.hasFocus()) return;
    ensureSoftphone();
  };
  window.setTimeout(connectWhenForeground, 300);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") connectWhenForeground();
  });
  window.addEventListener("focus", connectWhenForeground);
})();

/* source: amount-format.js */
/**
 * Общее форматирование денежных полей: группы по тысячам при вводе и краткая подсказка (млн / тыс.).
 */
(() => {
  const THIN_NBSP = '\u202f';

  function decimalsForCurrency(currency) {
    const c = (currency || '').toUpperCase();
    const intOnly = new Set(['VND', 'UGX', 'JPY']);
    return intOnly.has(c) ? 0 : 2;
  }

  function stripSeparators(raw) {
    return String(raw || '')
      .replace(/[\s\u202f\u00a0]/g, '')
      .replace(',', '.');
  }

  function parseAmount(raw) {
    if (raw == null) return 0;
    const s = stripSeparators(raw);
    const n = Number(s);
    return Number.isFinite(n) && n >= 0 ? n : 0;
  }

  function parseOptionalNumber(raw) {
    const s = String(raw || '')
      .replace(/[\s\u202f\u00a0]/g, '')
      .trim();
    if (!s) return null;
    const n = Number(s.replace(',', '.'));
    return Number.isFinite(n) ? n : null;
  }

  function formatGroupedDigits(intStr) {
    const digits = String(intStr || '').replace(/\D/g, '');
    if (!digits) return '';
    return digits.replace(/\B(?=(\d{3})+(?!\d))/g, THIN_NBSP);
  }

  function formatGroupedInt(n) {
    return formatGroupedDigits(String(Math.round(Math.abs(Number(n)))));
  }

  /**
   * Компактное отображение суммы: разбивает на млн/тыс без округления.
   * Пример: 7500 → "7 тыс", 1500000 → "1 млн 500 тыс".
   */
  function _compactParts(abs) {
    const mln = Math.floor(abs / 1_000_000);
    const tys = Math.floor((abs % 1_000_000) / 1_000);
    const parts = [];
    const t_mln = (window.upos_i18n && window.upos_i18n['num.mln']) || 'млн';
    const t_tys = (window.upos_i18n && window.upos_i18n['num.tys']) || 'тыс';
    if (mln) parts.push(`${mln}${THIN_NBSP}${t_mln}`);
    if (tys) parts.push(`${tys}${THIN_NBSP}${t_tys}`);
    return parts;
  }

  function formatCompact(amount, currency) {
    const n = Number(amount);
    if (!Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    const sign = n < 0 ? '−' : '';
    const cc = (currency || '').toUpperCase();

    if (abs === 0) return `${sign}0${THIN_NBSP}${cc}`;
    if (abs < 1000) return `${sign}${formatGroupedInt(abs)}${THIN_NBSP}${cc}`;
    const parts = _compactParts(abs);
    if (parts.length === 0)
      return `${sign}${formatGroupedInt(Math.round(abs))}${THIN_NBSP}${cc}`;
    return `${sign}${parts.join(THIN_NBSP)}${THIN_NBSP}${cc}`;
  }

  /** Масштаб без кода валюты (поле «курс» и т.п.). */
  function formatCompactBare(amount) {
    const n = Number(amount);
    if (!Number.isFinite(n)) return '';
    const abs = Math.abs(n);
    const sign = n < 0 ? '−' : '';
    if (abs === 0) return `${sign}0`;
    if (abs >= 1_000_000_000) {
      const t_mlrd = (window.upos_i18n && window.upos_i18n['num.mlrd']) || 'млрд';
      return `${sign}${formatGroupedInt(Math.round(abs / 1_000_000_000))}${THIN_NBSP}${t_mlrd}`;
    }
    if (abs < 1000) return `${sign}${formatGroupedInt(abs)}`;
    const parts = _compactParts(abs);
    if (parts.length === 0) return `${sign}${formatGroupedInt(Math.round(abs))}`;
    return `${sign}${parts.join(THIN_NBSP)}`;
  }

  function parseTypingSegments(raw) {
    const s = String(raw || '').replace(/[\s\u202f\u00a0]/g, '');
    let intDigits = '';
    let fracDigits = '';
    let seenDec = false;
    let hadDecimalSep = false;
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (c >= '0' && c <= '9') {
        if (!seenDec) intDigits += c;
        else fracDigits += c;
      } else if ((c === '.' || c === ',') && !seenDec) {
        seenDec = true;
        hadDecimalSep = true;
      }
    }
    const last = s.length ? s[s.length - 1] : '';
    const trailingSep = !!(hadDecimalSep && fracDigits.length === 0 && (last === '.' || last === ','));
    return { intDigits, fracDigits, trailingSep };
  }

  function digitsLeftOfCaret(s, caret) {
    let n = 0;
    const upto = Math.min(caret ?? 0, s.length);
    for (let i = 0; i < upto; i++) if (/\d/.test(s[i])) n++;
    return n;
  }

  function caretAfterDigitCount(display, count) {
    if (count <= 0) return 0;
    let seen = 0;
    for (let i = 0; i < display.length; i++) {
      if (/\d/.test(display[i])) {
        seen++;
        if (seen === count) return i + 1;
      }
    }
    return display.length;
  }

  /**
   * Курс / произвольные положительные дробные: до maxFrac знаков после запятой в вводе.
   */
  function rateDisplayAndNumber(raw, maxFrac) {
    const max = Number.isFinite(maxFrac) ? Math.max(0, Math.floor(maxFrac)) : 10;
    const { intDigits, fracDigits, trailingSep } = parseTypingSegments(raw);
    const intPart = intDigits.replace(/\D/g, '');
    let frac = fracDigits.replace(/\D/g, '').slice(0, max);

    if (!intPart && !frac && !trailingSep) return { display: '', parsed: NaN };

    const intShow = intPart ? formatGroupedDigits(intPart) : frac || trailingSep ? '0' : '';
    let display = intShow;
    if (trailingSep || frac.length) display += `,${frac}`;

    let parsed = NaN;
    if (!intPart && !frac.length && trailingSep) parsed = NaN;
    else if (trailingSep && frac.length === 0 && intPart.length)
      parsed = Number(parseInt(intPart, 10));
    else if (max === 0)
      parsed = intPart.length ? Number(parseInt(intPart, 10)) : NaN;
    else {
      const iNum = intPart.length ? parseInt(intPart, 10) : 0;
      if (frac.length)
        parsed = Number(`${iNum}.${(frac + '0'.repeat(max)).slice(0, max)}`);
      else parsed = Number(`${iNum}`);
    }
    return { display, parsed };
  }

  function buildMoneyDisplayAndNumber(raw, maxDecimals) {
    const md = Number.isFinite(maxDecimals) ? Math.max(0, Math.floor(maxDecimals)) : 2;
    const { intDigits, fracDigits, trailingSep } = parseTypingSegments(raw);
    const intPart = intDigits.replace(/\D/g, '');
    let frac = fracDigits.replace(/\D/g, '').slice(0, md);

    if (md === 0) {
      if (!intPart) return { display: '', parsed: NaN };
      return { display: formatGroupedDigits(intPart), parsed: Number(parseInt(intPart, 10)) };
    }

    const intShow = intPart ? formatGroupedDigits(intPart) : frac || trailingSep ? '0' : '';
    if (!intShow && !frac && !trailingSep) return { display: '', parsed: NaN };

    let display = intShow;
    if (trailingSep || frac.length) display += `,${frac}`;

    if (trailingSep && frac.length === 0) {
      const parsed = intPart.length ? Number(parseInt(intPart, 10)) : NaN;
      return { display, parsed };
    }

    const iNum = intPart.length ? parseInt(intPart, 10) : 0;
    const fd = `${frac}${'0'.repeat(md)}`.slice(0, md);
    let parsed = Number(`${iNum}.${fd}`);
    if (!intPart.length && !frac.length) parsed = NaN;
    parsed = Math.round(parsed * 10 ** md) / 10 ** md;
    return { display, parsed };
  }

  function formatInputElement(el, maxDecimals) {
    if (!el) return NaN;
    const caret = el.selectionStart ?? el.value.length;
    const k = digitsLeftOfCaret(el.value, caret);
    const { display, parsed } = buildMoneyDisplayAndNumber(el.value, maxDecimals);
    el.value = display;
    try {
      const newCaret = caretAfterDigitCount(display, k);
      el.setSelectionRange(newCaret, newCaret);
    } catch {
      /* ignore */
    }
    return parsed;
  }

  function formatRateInputElement(el, maxFrac) {
    if (!el) return NaN;
    const caret = el.selectionStart ?? el.value.length;
    const k = digitsLeftOfCaret(el.value, caret);
    const { display, parsed } = rateDisplayAndNumber(el.value, maxFrac);
    el.value = display;
    try {
      const newCaret = caretAfterDigitCount(display, k);
      el.setSelectionRange(newCaret, newCaret);
    } catch {
      /* ignore */
    }
    return parsed;
  }

  function setInputFromNumber(el, n, maxDecimals) {
    if (!el) return;
    if (!Number.isFinite(n) || n < 0) {
      el.value = '';
      return;
    }
    const md = Number.isFinite(maxDecimals) ? Math.max(0, Math.floor(maxDecimals)) : 2;
    if (md === 0) {
      el.value = formatGroupedInt(n);
      return;
    }
    const rounded = Math.round(n * 100) / 100;
    if (Number.isInteger(rounded)) {
      el.value = formatGroupedInt(rounded);
      return;
    }
    const [a, b] = rounded.toFixed(2).split('.');
    el.value = `${formatGroupedDigits(a)},${b}`;
  }

  function setRateInputFromNumber(el, n, maxFrac = 12) {
    if (!el) return;
    if (!Number.isFinite(n) || n < 0) {
      el.value = '';
      return;
    }
    const s = String(n);
    const [a, b0] = s.includes('.') ? s.split('.') : [s, ''];
    const b = (b0 + '0'.repeat(maxFrac)).slice(0, maxFrac).replace(/0+$/, '');
    el.value = b.length ? `${formatGroupedDigits(a)},${b}` : formatGroupedDigits(a);
  }

  function updateHintEl(hintEl, amount, currency) {
    if (!hintEl) return;
    const n = Number(amount);
    if (!Number.isFinite(n) || n <= 0) {
      hintEl.textContent = '';
      hintEl.hidden = true;
      return;
    }
    const cc = String(currency || '').trim().toUpperCase();
    hintEl.textContent = cc ? formatCompact(n, cc) : formatCompactBare(n);
    hintEl.hidden = false;
  }

  const api = {
    THIN_NBSP,
    decimalsForCurrency,
    parseAmount,
    parseOptionalNumber,
    stripSeparators,
    formatGroupedDigits,
    formatGroupedInt,
    formatCompact,
    formatCompactBare,
    parseTypingSegments,
    buildMoneyDisplayAndNumber,
    rateDisplayAndNumber,
    formatInputElement,
    formatRateInputElement,
    setInputFromNumber,
    setRateInputFromNumber,
    updateHintEl,
    digitsLeftOfCaret,
    caretAfterDigitCount,
  };

  (typeof globalThis !== 'undefined' ? globalThis : window).UPOS_AMOUNT = api;
})();

/* source: money-auto-format.js */
(() => {
  "use strict";

  const SELECTOR = "input[data-upos-money-format]";

  function amountApi() {
    return window.UPOS_AMOUNT || null;
  }

  function decimalsFor(input) {
    const raw = Number(input?.dataset?.uposMoneyDecimals);
    return Number.isFinite(raw) ? Math.max(0, Math.floor(raw)) : 0;
  }

  function format(input) {
    const api = amountApi();
    if (!api || !input) return;
    api.formatInputElement(input, decimalsFor(input));
  }

  function strip(input) {
    const api = amountApi();
    if (!api || !input) return;
    input.value = api.stripSeparators(input.value);
  }

  function enhanceInput(input) {
    if (!input || input.dataset.uposMoneyReady === "1") return;
    input.dataset.uposMoneyReady = "1";
    input.addEventListener("input", () => format(input));
    input.addEventListener("blur", () => format(input));
    if (input.value) format(input);
  }

  function enhanceAll(root = document) {
    root.querySelectorAll?.(SELECTOR).forEach(enhanceInput);
  }

  document.addEventListener("DOMContentLoaded", () => enhanceAll());

  document.addEventListener(
    "submit",
    (event) => {
      event.target?.querySelectorAll?.(SELECTOR).forEach(strip);
    },
    true
  );

  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType !== 1) return;
        if (node.matches?.(SELECTOR)) enhanceInput(node);
        enhanceAll(node);
      });
    });
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });

  window.UPOS_MONEY_AUTO = { enhanceAll, enhanceInput, format, strip };
})();

/* source: currency-meta.js */
/**
 * Метаданные валют для иконок/подписей в выпадающих списках и сайдбаре.
 */
(() => {
  const ACCENT = {
    UZS: 'oklch(0.72 0.12 155)',
    USD: 'oklch(0.72 0.11 235)',
    EUR: 'oklch(0.68 0.12 285)',
    RUB: 'oklch(0.72 0.18 35)',
    KZT: 'oklch(0.68 0.12 295)',
    GBP: 'oklch(0.72 0.14 295)',
    CNY: 'oklch(0.74 0.15 65)',
    AED: 'oklch(0.72 0.11 235)',
    TRY: 'oklch(0.72 0.15 340)',
    CHF: 'oklch(0.74 0.12 295)',
    JPY: 'oklch(0.74 0.12 10)',
    KRW: 'oklch(0.74 0.11 295)',
    VND: 'oklch(0.75 0.12 355)',
    UGX: 'oklch(0.73 0.11 295)',
    IDR: 'oklch(0.72 0.12 295)',
    default: 'oklch(0.65 0.08 250)',
  };

  function symbol(code) {
    const m = {
      USD: '$',
      EUR: '€',
      RUB: '₽',
      KZT: '₸',
      GBP: '£',
      TRY: '₺',
      UZS: '',
      JPY: '¥',
      CNY: '¥',
      KRW: '₩',
      CHF: `Fr.`,
      AED: `dh`,
    };
    return m[(code || '').toUpperCase()] || '';
  }

  /** Круг с двумя буквами кода ISO (без CDN флагов). */
  function iconHtml(code, px = 22) {
    const ccy = (code || '??').toUpperCase().slice(0, 3);
    const two = (ccy + 'XX').slice(0, 2);
    const fill = ACCENT[ccy] || ACCENT.default;
    const fs = px > 18 ? 8 : 7;
    const t = two.replace(/</g, '');
    return `<span class="upos-ccy-ic-wrap" aria-hidden="true"><svg class="upos-ccy-ic-svg" width="${px}" height="${px}" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="11" fill="${fill}"/><text x="12" y="14.5" text-anchor="middle" fill="#fff" font-size="${fs}px" font-weight="700" font-family="system-ui,sans-serif">${t}</text></svg></span>`;
  }

  function iconHtmlSmall(code) {
    return iconHtml(code, 18);
  }

  /** Текст в нативном option (до кастомного UI). */
  function optionLabel(code) {
    const c = (code || '').toUpperCase();
    const s = symbol(c);
    return s ? `${s}\u202f\u00b7\u202f${c}` : c;
  }

  window.UPOS_CCY = {
    ACCENT,
    symbol,
    iconHtml,
    iconHtmlSmall,
    optionLabel,
  };
})();

/* source: currency-select.js */
/**
 * Custom currency select: icon + currency code.
 */
(() => {
  const meta = () => window.UPOS_CCY;

  function closeAll(exceptWrap) {
    document.querySelectorAll('.upos-ccy-select.is-open').forEach((w) => {
      if (w !== exceptWrap) {
        w.classList.remove('is-open');
        const p = w.querySelector('.upos-ccy-select-panel');
        if (p) p.hidden = true;
      }
    });
  }

  function optionCode(opt) {
    return String(opt?.value || '').toUpperCase();
  }

  function optionBalanceLabel(opt) {
    const explicit = String(opt?.dataset?.balanceLabel || '').trim();
    if (explicit) return explicit;
    const text = String(opt?.textContent || '').replace(/\s+/g, ' ').trim();
    const match = text.match(/(?:^|·)\s*доступно\s+(.+)$/i);
    return match ? match[1].trim() : '';
  }

  function rebuildPanel(wrap, select) {
    const panel = wrap.querySelector('.upos-ccy-select-panel');
    if (!panel) return;
    panel.innerHTML = '';
    [...select.options].forEach((opt) => {
      const li = document.createElement('li');
      li.setAttribute('role', 'option');
      li.tabIndex = -1;
      const v = opt.value;
      li.dataset.value = v;
      li.className = 'upos-ccy-select-item';
      if (!v) {
        li.classList.add('is-placeholder');
        li.textContent = opt.textContent || '-';
        li.dataset.value = '';
      } else {
        const cc = meta();
        const code = optionCode(opt);
        const ic = cc && cc.iconHtmlSmall && code ? cc.iconHtmlSmall(code) : '';
        const balance = optionBalanceLabel(opt);
        const bal = balance ? `<span class="upos-ccy-select-item-balance">${escapeHtml(balance)}</span>` : '';
        if (balance) li.classList.add('has-balance');
        li.innerHTML = `${ic}<span class="upos-ccy-select-item-code">${escapeHtml(code)}</span>${bal}`;
      }
      if (opt.selected) li.classList.add('is-selected');
      panel.appendChild(li);
    });
  }

  function escapeHtml(s) {
    return String(s || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function syncButton(btn, select) {
    btn.disabled = select.disabled;
    const opt = select.options[select.selectedIndex];
    const v = select.value;
    const cc = meta();
    if (!opt || (!v && !opt.textContent.trim())) {
      btn.innerHTML = `<span class="upos-ccy-select-btn-ph">${escapeHtml(opt?.textContent || '...')}</span>`;
      return;
    }
    const code = v ? optionCode(opt) : '';
    const ic = cc && cc.iconHtmlSmall && code ? cc.iconHtmlSmall(code) : '';
    const balance = optionBalanceLabel(opt);
    const bal = balance ? `<span class="upos-ccy-select-item-balance">${escapeHtml(balance)}</span>` : '';
    const label = code
      ? `<span class="upos-ccy-select-btn-main">${ic}<span class="upos-ccy-select-btn-code">${escapeHtml(code)}</span></span>${bal}`
      : `<span class="upos-ccy-select-btn-plain">${escapeHtml(opt.textContent || '')}</span>`;
    btn.innerHTML = `${label}<svg class="upos-ccy-chevron" width="14" height="14" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg>`;
  }

  function enhanceCurrencySelect(select) {
    if (!select || select.dataset.ccyEnhanced === '1') return;
    const wrap = document.createElement('div');
    wrap.className = 'upos-ccy-select';
    select.parentNode.insertBefore(wrap, select);
    wrap.appendChild(select);

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'upos-ccy-select-btn';
    btn.setAttribute('aria-haspopup', 'listbox');
    btn.setAttribute('aria-expanded', 'false');

    const panel = document.createElement('ul');
    panel.className = 'upos-ccy-select-panel';
    panel.setAttribute('role', 'listbox');
    panel.hidden = true;

    wrap.insertBefore(btn, select);
    wrap.insertBefore(panel, select);
    select.classList.add('upos-ccy-select-native');
    select.dataset.ccyEnhanced = '1';

    rebuildPanel(wrap, select);
    syncButton(btn, select);

    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const wasOpen = wrap.classList.contains('is-open');
      if (wasOpen) {
        wrap.classList.remove('is-open');
        panel.hidden = true;
        btn.setAttribute('aria-expanded', 'false');
        return;
      }
      closeAll(null);
      rebuildPanel(wrap, select);
      wrap.classList.add('is-open');
      panel.hidden = false;
      btn.setAttribute('aria-expanded', 'true');
    });

    wrap.addEventListener('click', (e) => {
      e.stopPropagation();
    });

    panel.addEventListener('click', (ev) => {
      const item = ev.target.closest('.upos-ccy-select-item');
      if (!item || wrap !== item.closest('.upos-ccy-select')) return;
      const val = item.dataset.value;
      if (typeof val !== 'string') return;
      const opt = [...select.options].find((o) => o.value === val);
      if (!opt || opt.disabled) return;
      select.value = val;
      select.dispatchEvent(new Event('change', { bubbles: true }));
      select.dispatchEvent(new Event('input', { bubbles: true }));
      rebuildPanel(wrap, select);
      syncButton(btn, select);
      wrap.classList.remove('is-open');
      panel.hidden = true;
      btn.setAttribute('aria-expanded', 'false');
    });

    select.addEventListener('change', () => {
      rebuildPanel(wrap, select);
      syncButton(btn, select);
    });

    const mo = new MutationObserver(() => {
      rebuildPanel(wrap, select);
      syncButton(btn, select);
    });
    mo.observe(select, { childList: true, subtree: true, attributes: true, attributeFilter: ['disabled'] });

    document.addEventListener('click', () => {
      wrap.classList.remove('is-open');
      panel.hidden = true;
      btn.setAttribute('aria-expanded', 'false');
    });

    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape' && wrap.classList.contains('is-open')) {
        wrap.classList.remove('is-open');
        panel.hidden = true;
        btn.setAttribute('aria-expanded', 'false');
      }
    });
  }

  function upgradeAll(scope) {
    const root = scope || document;
    root.querySelectorAll('select[data-ccy-enhance]').forEach(enhanceCurrencySelect);
  }

  window.UPOS_CCY_SELECT = { enhanceCurrencySelect, upgradeAll };
})();

/* source: avatar-upload.js */
(function () {
  function t(key, fallback, vars) {
    const pack = window.upos_i18n || {};
    let text = pack[key] || fallback || key;
    if (vars && typeof vars === 'object') {
      Object.keys(vars).forEach((name) => {
        text = String(text).replace(new RegExp('\\{' + name + '\\}', 'g'), String(vars[name]));
      });
    }
    return text;
  }

  const trigger = document.getElementById('sidebar-avatar-trigger');
  const input = document.getElementById('sidebar-avatar-input');
  if (!trigger || !input) return;

  trigger.addEventListener('click', () => input.click());

  input.addEventListener('change', async () => {
    const file = input.files[0];
    if (!file) return;

    // Optional: client side size check
    if (file.size > 10 * 1024 * 1024) {
      alert(t('avatar.err.too_large', 'Файл слишком большой (макс 10МБ)'));
      return;
    }

    const formData = new FormData();
    formData.append('file', file);

    // Show loading state
    const originalContent = trigger.innerHTML;
    trigger.style.opacity = '0.5';
    trigger.style.pointerEvents = 'none';

    try {
      const csrf = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')
        || document.querySelector('input[name="csrf_token"]')?.value
        || '';
      const res = await fetch('/api/user/avatar', {
        method: 'POST',
        headers: { 'X-CSRF-Token': csrf },
        body: formData
      });
      const body = await res.json();
      if (body.ok) {
        location.reload();
      } else {
        alert(t('avatar.err.upload', 'Ошибка при загрузке: {error}', { error: body.error || t('avatar.err.unknown', 'неизвестно') }));
        trigger.innerHTML = originalContent;
        trigger.style.opacity = '';
        trigger.style.pointerEvents = '';
      }
    } catch (e) {
      alert(t('avatar.err.network', 'Ошибка сети или сервера'));
      trigger.innerHTML = originalContent;
      trigger.style.opacity = '';
      trigger.style.pointerEvents = '';
    }
  });
})();

/* source: workspace-switcher.js */
(function () {
  const storagePrefix = "upos.workspaceSwitcher.openOrder.";

  function storageKey() {
    const userId = (document.body && document.body.dataset.userId) || "anonymous";
    return storagePrefix + userId;
  }

  function readOrder() {
    try {
      const parsed = JSON.parse(localStorage.getItem(storageKey()) || "[]");
      return Array.isArray(parsed) ? parsed.filter(Boolean).map(String) : [];
    } catch (_) {
      return [];
    }
  }

  function writeOrder(order) {
    try {
      localStorage.setItem(storageKey(), JSON.stringify(order));
    } catch (_) {
      // Storage can be unavailable in private or restricted browser modes.
    }
  }

  function organizationId(form) {
    const input = form.querySelector('input[name="organization_id"]');
    return input ? String(input.value || "").trim() : "";
  }

  function rememberOrganization(orgId) {
    if (!orgId) return;
    const order = readOrder();
    if (order.includes(orgId)) return;
    order.push(orgId);
    writeOrder(order);
  }

  function sortSwitcher(scope) {
    const panel = scope.querySelector(".workspace-options");
    if (!panel) return;

    const forms = Array.from(panel.querySelectorAll(".workspace-option-form"));
    if (!forms.length) return;

    const order = readOrder();
    const byId = new Map(order.map((orgId, index) => [orgId, index]));
    let changed = false;

    forms.forEach((form, index) => {
      form.dataset.workspaceOriginalIndex = String(index);
      const orgId = organizationId(form);
      if (form.querySelector(".workspace-option.active") && orgId && !byId.has(orgId)) {
        rememberOrganization(orgId);
        byId.set(orgId, order.length);
        order.push(orgId);
        changed = true;
      }
    });

    forms
      .slice()
      .sort((left, right) => {
        const leftId = organizationId(left);
        const rightId = organizationId(right);
        const leftSeen = byId.has(leftId);
        const rightSeen = byId.has(rightId);
        if (leftSeen && rightSeen) return byId.get(leftId) - byId.get(rightId);
        if (leftSeen) return -1;
        if (rightSeen) return 1;
        return Number(left.dataset.workspaceOriginalIndex || 0) - Number(right.dataset.workspaceOriginalIndex || 0);
      })
      .forEach((form) => panel.appendChild(form));

    if (changed) writeOrder(order);
  }

  function setupSwitcher(scope) {
    sortSwitcher(scope);
    scope.querySelectorAll(".workspace-option-form").forEach((form) => {
      form.addEventListener("submit", () => rememberOrganization(organizationId(form)));
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    document.querySelectorAll("[data-workspace-switcher]").forEach(setupSwitcher);
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    document.querySelectorAll("[data-workspace-switcher][open]").forEach((scope) => {
      scope.open = false;
    });
  });

  document.addEventListener("click", (event) => {
    const target = event.target instanceof Element ? event.target : null;
    document.querySelectorAll("[data-workspace-switcher][open]").forEach((scope) => {
      if (!target || !scope.contains(target)) scope.open = false;
    });
  });
})();

/* source: device-heartbeat.js */
/* Keeps the authenticated device session fresh without loading settings UI. */
(() => {
  "use strict";

  const HEARTBEAT_KEY = "upos:device-heartbeat:last";

  function sendHeartbeat() {
    if (document.body?.getAttribute("data-device-heartbeat") !== "1") return;

    const now = Date.now();
    try {
      const lastHeartbeat = Number(localStorage.getItem(HEARTBEAT_KEY) || 0);
      if (now - lastHeartbeat < 45_000) return;
      localStorage.setItem(HEARTBEAT_KEY, String(now));
    } catch {
      /* Storage may be unavailable in private browsing. */
    }

    const meta = {
      language: navigator.language || "",
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "",
      platform: navigator.platform || "",
    };
    void fetch("/api/me/devices/heartbeat", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ client_meta: meta }),
    }).catch(() => null);
  }

  function start() {
    sendHeartbeat();
    window.setInterval(sendHeartbeat, 60_000);
  }

  if (document.prerendering) {
    document.addEventListener("prerenderingchange", start, { once: true });
  } else {
    start();
  }
})();
